def _action_q_temporal_readiness_plateau_stop_reason(
    *,
    q_fit_target_mode: str,
    step: int,
    selected_target_stage_passed: bool,
    temporal_transfer_readiness_passed: bool,
    temporal_plateau_checks: int,
    temporal_plateau_patience_checks: int,
    temporal_plateau_min_steps: int,
) -> str | None:
    if str(q_fit_target_mode) != "temporal_delta_relative_to_old_q_v1":
        return None
    if not bool(selected_target_stage_passed):
        return None
    if bool(temporal_transfer_readiness_passed):
        return None
    if int(step) < int(temporal_plateau_min_steps):
        return None
    if int(temporal_plateau_checks) < int(temporal_plateau_patience_checks):
        return None
    return "temporal_readiness_plateau"


def _action_q_actor_update_suppressed_by_transfer_readiness(
    *,
    actor_advantage_source: str,
    sampled_action_q_residual_actor_sources: Iterable[str],
    transfer_requested: bool,
    q_fit_passed: bool,
    transfer_report: Mapping[str, Any] | None,
) -> bool:
    if str(actor_advantage_source) not in set(sampled_action_q_residual_actor_sources):
        return False
    if not bool(transfer_requested) or not bool(q_fit_passed):
        return False
    report = transfer_report or {}
    return (
        not bool(report.get("passed"))
        or bool(report.get("transferActivationSuppressedByTemporalReadiness"))
    )


