ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE = "q_backed_single_residual_v1"


def _normalize_q_backed_actor_residual_mode(mode: str | None) -> str:
    text = str(mode or Q_BACKED_ACTOR_RESIDUAL_DISABLED).strip().lower()
    if text in {"", "disabled", "none", "off", "false"}:
        return Q_BACKED_ACTOR_RESIDUAL_DISABLED
    if text in {
        Q_BACKED_ACTOR_RESIDUAL_MEAN_LEGAL_ACTION_Q,
        "mean_legal_q_residual_v1",
        "q_backed_mean_legal_residual_v1",
    }:
        return Q_BACKED_ACTOR_RESIDUAL_MEAN_LEGAL_ACTION_Q
    raise ValueError(f"unknown q-backed actor residual mode: {mode!r}")


def _normalize_actor_residual_contract(contract: str | None) -> str:
    text = str(contract or ACTOR_RESIDUAL_CONTRACT_LEGACY).strip().lower()
    if text in {"", "legacy", "default", "independent", ACTOR_RESIDUAL_CONTRACT_LEGACY}:
        return ACTOR_RESIDUAL_CONTRACT_LEGACY
    if text in {"q_backed_single", "qbacked_single", ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE}:
        return ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE
    raise ValueError(f"unknown actor residual contract: {contract!r}")


def _state_action_prior_free_action_mask_values(
    action_feature_names: Sequence[str],
    card_feature_count: int,
) -> list[float]:
    mask: list[float] = []
    for name in action_feature_names:
        text = str(name)
        broad = any(text.startswith(prefix) for prefix in STATE_ACTION_PRIOR_FREE_BROAD_ACTION_PREFIXES)
        mask.append(0.0 if broad else 1.0)
    mask.extend([1.0] * (2 * max(0, int(card_feature_count))))
    return mask


@dataclass
class YgoStyleActionSetPolicyScorer:
    globalFeatureNames: list[str]
    actionFeatureNames: list[str]
    cardFeatureNames: list[str]
    inputDim: int
    hiddenDim: int
    w1: list[list[float]] = field(default_factory=list)
    b1: list[float] = field(default_factory=list)
    w2: list[float] = field(default_factory=list)
    b2: float = 0.0
    valueW: list[float] = field(default_factory=list)
    valueB: float = 0.0
    valueDomainBiasMode: str = "disabled"
    valueDomainBiases: dict[str, float] = field(default_factory=dict)
    modelVersion: str = YGO_STYLE_ACTION_SET_POLICY_VERSION
    historyFeatureNames: list[str] = field(default_factory=list)
    policyAnchorKlTraining: bool = False
    anchorKlWeight: float = 0.0
    anchorKlTemperature: float = 1.0
    anchorKlDecisionWeights: dict[str, float] = field(default_factory=dict)
    retentionKlMode: str = "disabled"
    retentionKlReport: dict[str, Any] = field(default_factory=dict)
    decisionTrainingWeights: dict[str, float] = field(default_factory=dict)
    decisionResidualPolicyMode: str = "disabled"
    decisionResidualWeights: dict[str, list[float]] = field(default_factory=dict)
    allowSelectedActionFallback: bool = False
    directPolicyTargetMode: str = "causal_or_explicit_only"
    runtimeAuxTrainingObjective: str = RUNTIME_AUX_TRAINING_OBJECTIVE_VALUE_DISTRIBUTION
    runtimeAuxTrainingDiagnostics: dict[str, Any] = field(default_factory=dict)
    runtimeAuxOutputScale: float = 1.0
    centerLegalSidecarScores: bool = False
    runtimeCalibratedSidecarTraining: bool = False
    outcomePolicyGradientTraining: bool = False
    trainingResolvedDevice: str = "unknown"
    recurrentTrainingMode: str = "disabled"
    recurrentHiddenDim: int = 0
    recurrentDomainNames: list[str] = field(default_factory=list)
    recurrentGruWeightIh: list[list[float]] = field(default_factory=list)
    recurrentGruWeightHh: list[list[float]] = field(default_factory=list)
    recurrentGruBiasIh: list[float] = field(default_factory=list)
    recurrentGruBiasHh: list[float] = field(default_factory=list)
    recurrentPolicyW1: list[list[float]] = field(default_factory=list)
    recurrentPolicyB1: list[float] = field(default_factory=list)
    recurrentPolicyW2: list[float] = field(default_factory=list)
    recurrentPolicyB2: float = 0.0
    recurrentValueW: list[float] = field(default_factory=list)
    recurrentValueB: float = 0.0
    stateActionInteractionMode: str = "disabled"
    stateActionInteractionRank: int = 0
    stateActionConditionDomainNames: list[str] = field(default_factory=list)
    stateActionStateW: list[list[float]] = field(default_factory=list)
    stateActionStateB: list[float] = field(default_factory=list)
    stateActionStateCenter: list[float] = field(default_factory=list)
    stateActionActionW: list[list[float]] = field(default_factory=list)
    stateActionActionB: list[float] = field(default_factory=list)
    stateActionOutputW: list[float] = field(default_factory=list)
    stateActionReferenceStateW: list[list[float]] = field(default_factory=list)
    stateActionReferenceStateB: list[float] = field(default_factory=list)
    stateActionReferenceActionW: list[list[float]] = field(default_factory=list)
    stateActionReferenceActionB: list[float] = field(default_factory=list)
    stateActionReferenceOutputW: list[float] = field(default_factory=list)
    stateActionReferenceSignatureW: list[list[float]] = field(default_factory=list)
    stateActionCrossW: list[list[float]] = field(default_factory=list)
    stateActionSignatureCrossW: list[list[list[float]]] = field(default_factory=list)
    stateActionReferenceSignatureCrossW: list[list[list[float]]] = field(default_factory=list)
    stateActionSignatureNames: list[str] = field(default_factory=list)
    stateActionSignatureW: list[list[float]] = field(default_factory=list)
    actionQResidualMode: str = "disabled"
    actionQResidualFeatureDim: int = 0
    actionQResidualW: list[float] = field(default_factory=list)
    actionQResidualB: float = 0.0
    actionQResidualArchitecture: str = "disabled"
    actionQResidualStateDim: int = 0
    actionQResidualActionDim: int = 0
    actionQResidualRank: int = 0
    actionQResidualStateW: list[list[float]] = field(default_factory=list)
    actionQResidualStateB: list[float] = field(default_factory=list)
    actionQResidualActionW: list[list[float]] = field(default_factory=list)
    actionQResidualOutputW: list[float] = field(default_factory=list)
    qBackedActorResidualMode: str = Q_BACKED_ACTOR_RESIDUAL_DISABLED
    actorResidualContract: str = ACTOR_RESIDUAL_CONTRACT_LEGACY
    _numpyWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _decisionResidualNumpyWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _recurrentNumpyWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _recurrentNumpyGruWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _stateActionInteractionNumpyWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _actionQResidualNumpyWeightCache: Any = field(default=None, init=False, repr=False, compare=False)
    _recurrentStateCache: dict[str, list[float]] = field(default_factory=dict, init=False, repr=False, compare=False)
    _recurrentRowInitialContextCache: dict[str, list[float]] = field(default_factory=dict, init=False, repr=False, compare=False)
    _recurrentRowContextCache: dict[str, list[float]] = field(default_factory=dict, init=False, repr=False, compare=False)
    _runtimeStateValueCache: dict[int, float] = field(default_factory=dict, init=False, repr=False, compare=False)

    def validate_shape(self) -> None:
        input_dim = int(self.inputDim)
        hidden_dim = int(self.hiddenDim)
        expected_input_dim = (
            len(self.globalFeatureNames)
            + len(self.historyFeatureNames)
            + len(self.actionFeatureNames)
            + 3 * len(self.cardFeatureNames)
        )
        if input_dim != expected_input_dim:
            raise ValueError(
                f"inputDim mismatch: declared {input_dim}, expected {expected_input_dim} from feature names"
            )
        if hidden_dim < 0:
            raise ValueError(f"hiddenDim must be non-negative: {hidden_dim}")
        if len(self.w1) != hidden_dim:
            raise ValueError(f"w1 shape mismatch: expected {hidden_dim} rows, got {len(self.w1)}")
        for index, row in enumerate(self.w1):
            if len(row) != input_dim:
                raise ValueError(f"w1 shape mismatch at row {index}: expected {input_dim}, got {len(row)}")
        if len(self.b1) != hidden_dim:
            raise ValueError(f"b1 shape mismatch: expected {hidden_dim}, got {len(self.b1)}")
        if len(self.w2) != hidden_dim:
            raise ValueError(f"w2 shape mismatch: expected {hidden_dim}, got {len(self.w2)}")
        expected_value_dim = len(self.globalFeatureNames) + len(self.historyFeatureNames) + len(self.cardFeatureNames)
        if self.valueW and len(self.valueW) != expected_value_dim:
            raise ValueError(
                f"value head shape mismatch: expected {expected_value_dim} weights, got {len(self.valueW)}"
            )
        if self._decision_residual_enabled():
            for key, weights in sorted((self.decisionResidualWeights or {}).items()):
                if len(weights) != input_dim:
                    raise ValueError(
                        f"decision residual weight shape mismatch for {key!r}: expected {input_dim}, got {len(weights)}"
                    )
        if self._state_action_interaction_enabled():
            rank = int(self.stateActionInteractionRank)
            mode = _normalize_state_action_interaction_mode(self.stateActionInteractionMode)
            expected_action_dim = len(self.actionFeatureNames) + 2 * len(self.cardFeatureNames)
            if _state_action_mode_uses_legal_set_context(mode):
                expected_action_dim *= 2
            expected_state_action_state_dim = expected_value_dim + len(self.stateActionConditionDomainNames)
            if mode == "signature_full_cross_delta_v1":
                expected_state_action_state_dim += expected_value_dim
            if _state_action_mode_uses_recurrent_context(mode):
                if not self._recurrent_enabled():
                    raise ValueError("recurrent state-action interaction requires recurrentTrainingMode")
                expected_state_action_state_dim += int(self.recurrentHiddenDim) + len(self.recurrentDomainNames)
            if rank <= 0:
                raise ValueError("state-action interaction rank must be positive when enabled")
            if mode == "signature_state_linear_v1":
                if len(self.stateActionSignatureNames) != len(self.stateActionSignatureW):
                    raise ValueError("state-action signature names/weights shape mismatch")
                expected_signature_dim = expected_state_action_state_dim + expected_action_dim
                for row in self.stateActionSignatureW:
                    if len(row) != expected_signature_dim:
                        raise ValueError("state-action signature feature dimension mismatch")
                return
            if mode == "signature_mlp_delta_v1":
                if len(self.stateActionStateW) != rank or len(self.stateActionStateB) != rank:
                    raise ValueError("state-action signature MLP projection shape mismatch")
                expected_concat_dim = expected_state_action_state_dim + expected_action_dim
                for row in self.stateActionStateW:
                    if len(row) != expected_concat_dim:
                        raise ValueError("state-action signature MLP input dimension mismatch")
                if len(self.stateActionSignatureNames) != len(self.stateActionSignatureW):
                    raise ValueError("state-action signature names/weights shape mismatch")
                for row in self.stateActionSignatureW:
                    if len(row) != rank:
                        raise ValueError("state-action signature MLP readout dimension mismatch")
                return
            if mode == "signature_low_rank_delta_v1":
                if len(self.stateActionStateW) != rank or len(self.stateActionStateB) != rank:
                    raise ValueError("state-action signature low-rank state projection shape mismatch")
                if len(self.stateActionActionW) != rank or len(self.stateActionActionB) != rank:
                    raise ValueError("state-action signature low-rank action projection shape mismatch")
                for row in self.stateActionStateW:
                    if len(row) != expected_state_action_state_dim:
                        raise ValueError("state-action signature low-rank state input dimension mismatch")
                for row in self.stateActionActionW:
                    if len(row) != expected_action_dim:
                        raise ValueError("state-action signature low-rank action input dimension mismatch")
                if len(self.stateActionSignatureNames) != len(self.stateActionSignatureW):
                    raise ValueError("state-action signature names/weights shape mismatch")
                for row in self.stateActionSignatureW:
                    if len(row) != rank:
                        raise ValueError("state-action signature low-rank readout dimension mismatch")
                if self.stateActionReferenceSignatureW:
                    if len(self.stateActionReferenceSignatureW) != len(self.stateActionSignatureW):
                        raise ValueError("state-action signature low-rank reference readout shape mismatch")
                    for row in self.stateActionReferenceSignatureW:
                        if len(row) != rank:
                            raise ValueError("state-action signature low-rank reference readout dimension mismatch")
                return
            if mode == "signature_full_cross_delta_v1":
                if len(self.stateActionSignatureNames) != len(self.stateActionSignatureCrossW):
                    raise ValueError("state-action signature full-cross names/weights shape mismatch")
                for matrix in self.stateActionSignatureCrossW:
                    if len(matrix) != expected_state_action_state_dim:
                        raise ValueError("state-action signature full-cross state dimension mismatch")
                    for row in matrix:
                        if len(row) != expected_action_dim:
                            raise ValueError("state-action signature full-cross action dimension mismatch")
                if self.stateActionReferenceSignatureCrossW:
                    if len(self.stateActionReferenceSignatureCrossW) != len(self.stateActionSignatureCrossW):
                        raise ValueError("state-action signature full-cross reference shape mismatch")
                    for matrix in self.stateActionReferenceSignatureCrossW:
                        if len(matrix) != expected_state_action_state_dim:
                            raise ValueError("state-action signature full-cross reference state dimension mismatch")
                        for row in matrix:
                            if len(row) != expected_action_dim:
                                raise ValueError("state-action signature full-cross reference action dimension mismatch")
                return
            if mode == "legal_set_delta_ranker_v1":
                if len(self.stateActionStateW) != rank or len(self.stateActionStateB) != rank:
                    raise ValueError("legal-set delta ranker projection shape mismatch")
                if len(self.stateActionActionW) != rank or len(self.stateActionActionB) != rank:
                    raise ValueError("legal-set delta ranker action projection shape mismatch")
                if len(self.stateActionOutputW) != rank:
                    raise ValueError("legal-set delta ranker output weight shape mismatch")
                for row in self.stateActionStateW:
                    if len(row) != expected_state_action_state_dim:
                        raise ValueError("legal-set delta ranker state input dimension mismatch")
                for row in self.stateActionActionW:
                    if len(row) != expected_action_dim:
                        raise ValueError("legal-set delta ranker action input dimension mismatch")
                if self.stateActionReferenceStateW:
                    if len(self.stateActionReferenceStateW) != rank or len(self.stateActionReferenceStateB) != rank:
                        raise ValueError("legal-set delta ranker reference state projection shape mismatch")
                    if len(self.stateActionReferenceActionW) != rank or len(self.stateActionReferenceActionB) != rank:
                        raise ValueError("legal-set delta ranker reference action projection shape mismatch")
                    if len(self.stateActionReferenceOutputW) != rank:
                        raise ValueError("legal-set delta ranker reference output weight shape mismatch")
                    for row in self.stateActionReferenceStateW:
                        if len(row) != expected_state_action_state_dim:
                            raise ValueError("legal-set delta ranker reference state input dimension mismatch")
                    for row in self.stateActionReferenceActionW:
                        if len(row) != expected_action_dim:
                            raise ValueError("legal-set delta ranker reference action input dimension mismatch")
                return
            if mode in {
                "prior_free_legal_ranker_v1",
                "prior_free_recurrent_legal_ranker_v1",
                "legal_set_context_ranker_v1",
                "legal_set_recurrent_context_ranker_v1",
            }:
                if len(self.stateActionStateW) != rank or self.stateActionStateB:
                    raise ValueError("legal-set ranker state projection shape mismatch")
                if len(self.stateActionActionW) != rank or self.stateActionActionB:
                    raise ValueError("legal-set ranker action projection shape mismatch")
                if len(self.stateActionOutputW) != rank:
                    raise ValueError("legal-set ranker output weight shape mismatch")
                if mode in {
                    "prior_free_legal_ranker_v1",
                    "prior_free_recurrent_legal_ranker_v1",
                } and len(self.stateActionStateCenter) != expected_state_action_state_dim:
                    raise ValueError("prior-free legal ranker state center dimension mismatch")
                for row in self.stateActionStateW:
                    if len(row) != expected_state_action_state_dim:
                        raise ValueError("legal-set ranker state input dimension mismatch")
                for row in self.stateActionActionW:
                    if len(row) != expected_action_dim:
                        raise ValueError("legal-set ranker action input dimension mismatch")
                if self.stateActionReferenceStateW:
                    if len(self.stateActionReferenceStateW) != rank or self.stateActionReferenceStateB:
                        raise ValueError("legal-set ranker reference state projection shape mismatch")
                    if len(self.stateActionReferenceActionW) != rank or self.stateActionReferenceActionB:
                        raise ValueError("legal-set ranker reference action projection shape mismatch")
                    if len(self.stateActionReferenceOutputW) != rank:
                        raise ValueError("legal-set ranker reference output weight shape mismatch")
                    for row in self.stateActionReferenceStateW:
                        if len(row) != expected_state_action_state_dim:
                            raise ValueError("legal-set ranker reference state input dimension mismatch")
                    for row in self.stateActionReferenceActionW:
                        if len(row) != expected_action_dim:
                            raise ValueError("legal-set ranker reference action input dimension mismatch")
                return
            if mode in {"mlp_refdelta_v1", "mlp_recurrent_refdelta_v1"}:
                expected_concat_dim = expected_state_action_state_dim + expected_action_dim
                if len(self.stateActionStateW) != rank or len(self.stateActionStateB) != rank:
                    raise ValueError("state-action MLP state-action projection shape mismatch")
                if len(self.stateActionOutputW) != rank:
                    raise ValueError("state-action MLP output weight shape mismatch")
                if len(self.stateActionReferenceStateW) != rank or len(self.stateActionReferenceStateB) != rank:
                    raise ValueError("state-action MLP reference projection shape mismatch")
                if len(self.stateActionReferenceOutputW) != rank:
                    raise ValueError("state-action MLP reference output weight shape mismatch")
                for row in self.stateActionStateW:
                    if len(row) != expected_concat_dim:
                        raise ValueError("state-action MLP input dimension mismatch")
                for row in self.stateActionReferenceStateW:
                    if len(row) != expected_concat_dim:
                        raise ValueError("state-action MLP reference input dimension mismatch")
                return
            if mode in {"full_cross_v1", "full_cross_recurrent_v1"}:
                if len(self.stateActionCrossW) != expected_state_action_state_dim:
                    raise ValueError("state-action full-cross state dimension mismatch")
                for row in self.stateActionCrossW:
                    if len(row) != expected_action_dim:
                        raise ValueError("state-action full-cross action dimension mismatch")
                return
            if len(self.stateActionStateW) != rank or len(self.stateActionStateB) != rank:
                raise ValueError("state-action interaction state projection shape mismatch")
            if len(self.stateActionActionW) != rank or len(self.stateActionActionB) != rank:
                raise ValueError("state-action interaction action projection shape mismatch")
            for row in self.stateActionStateW:
                if len(row) != expected_state_action_state_dim:
                    raise ValueError("state-action interaction state input dimension mismatch")
            for row in self.stateActionActionW:
                if len(row) != expected_action_dim:
                    raise ValueError("state-action interaction action input dimension mismatch")
            if mode == "low_rank_v2" and len(self.stateActionOutputW) != rank:
                raise ValueError("state-action interaction output weight shape mismatch")
            if mode == "low_rank_v3":
                if len(self.stateActionReferenceStateW) != rank or len(self.stateActionReferenceStateB) != rank:
                    raise ValueError("state-action interaction reference state projection shape mismatch")
                if len(self.stateActionReferenceActionW) != rank or len(self.stateActionReferenceActionB) != rank:
                    raise ValueError("state-action interaction reference action projection shape mismatch")
                for row in self.stateActionReferenceStateW:
                    if len(row) != expected_state_action_state_dim:
                        raise ValueError("state-action interaction reference state input dimension mismatch")
                for row in self.stateActionReferenceActionW:
                    if len(row) != expected_action_dim:
                        raise ValueError("state-action interaction reference action input dimension mismatch")
        if self._recurrent_enabled():
            recurrent_hidden_dim = int(self.recurrentHiddenDim)
            domain_dim = len(self.recurrentDomainNames)
            if len(self.recurrentGruWeightIh) != 3 * recurrent_hidden_dim:
                raise ValueError("recurrent GRU input weight shape mismatch")
            if len(self.recurrentGruWeightHh) != 3 * recurrent_hidden_dim:
                raise ValueError("recurrent GRU hidden weight shape mismatch")
            for row in self.recurrentGruWeightIh:
                if len(row) != expected_value_dim + domain_dim:
                    raise ValueError("recurrent GRU input dimension mismatch")
            for row in self.recurrentGruWeightHh:
                if len(row) != recurrent_hidden_dim:
                    raise ValueError("recurrent GRU hidden dimension mismatch")
            if (
                len(self.recurrentGruBiasIh) != 3 * recurrent_hidden_dim
                or len(self.recurrentGruBiasHh) != 3 * recurrent_hidden_dim
            ):
                raise ValueError("recurrent GRU bias shape mismatch")
            recurrent_policy_input_dim = input_dim + recurrent_hidden_dim + domain_dim
            if len(self.recurrentPolicyB1) != len(self.recurrentPolicyW1):
                raise ValueError("recurrent policy first-layer bias shape mismatch")
            for row in self.recurrentPolicyW1:
                if len(row) != recurrent_policy_input_dim:
                    raise ValueError("recurrent policy input dimension mismatch")
            if len(self.recurrentPolicyW2) != len(self.recurrentPolicyW1):
                raise ValueError("recurrent policy output weight shape mismatch")
            if self.recurrentValueW and len(self.recurrentValueW) != recurrent_hidden_dim + domain_dim:
                raise ValueError("recurrent value head shape mismatch")
        if str(self.actionQResidualMode or "disabled").strip().lower() not in {"", "disabled", "none", "off"}:
            architecture = str(self.actionQResidualArchitecture or "").strip().lower()
            if architecture == ACTION_Q_RESIDUAL_DUELING_ARCHITECTURE:
                state_dim = int(self.actionQResidualStateDim)
                action_dim = int(self.actionQResidualActionDim)
                rank = int(self.actionQResidualRank)
                if state_dim <= 0 or action_dim <= 0 or rank <= 0:
                    raise ValueError("action-Q residual critic requires positive state/action/rank dimensions")
                if len(self.actionQResidualStateW) != rank or len(self.actionQResidualStateB) != rank:
                    raise ValueError("action-Q residual state projection shape mismatch")
                if len(self.actionQResidualActionW) != rank:
                    raise ValueError("action-Q residual action projection shape mismatch")
                if len(self.actionQResidualOutputW) != rank:
                    raise ValueError("action-Q residual output weight shape mismatch")
                for row in self.actionQResidualStateW:
                    if len(row) != state_dim:
                        raise ValueError("action-Q residual state input dimension mismatch")
                for row in self.actionQResidualActionW:
                    if len(row) != action_dim:
                        raise ValueError("action-Q residual action input dimension mismatch")
            elif architecture == ACTION_Q_RESIDUAL_FULL_CROSS_ARCHITECTURE:
                state_dim = int(self.actionQResidualStateDim)
                action_dim = int(self.actionQResidualActionDim)
                rank = int(self.actionQResidualRank)
                if state_dim <= 0 or action_dim <= 0 or rank <= 0:
                    raise ValueError("action-Q residual full-cross critic requires positive state/action/rank dimensions")
                if len(self.actionQResidualStateW) != rank or len(self.actionQResidualStateB) != rank:
                    raise ValueError("action-Q residual full-cross state projection shape mismatch")
                if len(self.actionQResidualActionW) != rank:
                    raise ValueError("action-Q residual full-cross action projection shape mismatch")
                if int(self.actionQResidualFeatureDim) != rank * rank:
                    raise ValueError("action-Q residual full-cross feature dimension mismatch")
                if len(self.actionQResidualOutputW) != rank * rank:
                    raise ValueError("action-Q residual full-cross output weight shape mismatch")
                for row in self.actionQResidualStateW:
                    if len(row) != state_dim:
                        raise ValueError("action-Q residual full-cross state input dimension mismatch")
                for row in self.actionQResidualActionW:
                    if len(row) != action_dim:
                        raise ValueError("action-Q residual full-cross action input dimension mismatch")
            elif architecture == ACTION_Q_RESIDUAL_MLP_ARCHITECTURE:
                state_dim = int(self.actionQResidualStateDim)
                action_dim = int(self.actionQResidualActionDim)
                rank = int(self.actionQResidualRank)
                if state_dim <= 0 or action_dim <= 0 or rank <= 0:
                    raise ValueError("action-Q residual MLP critic requires positive state/action/rank dimensions")
                if len(self.actionQResidualStateW) != rank or len(self.actionQResidualStateB) != rank:
                    raise ValueError("action-Q residual MLP input projection shape mismatch")
                if self.actionQResidualActionW:
                    raise ValueError("action-Q residual MLP stores no separate action projection")
                if len(self.actionQResidualOutputW) != rank:
                    raise ValueError("action-Q residual MLP output weight shape mismatch")
                input_dim = state_dim + action_dim
                for row in self.actionQResidualStateW:
                    if len(row) != input_dim:
                        raise ValueError("action-Q residual MLP input dimension mismatch")
            elif architecture == ACTION_Q_RESIDUAL_LEGAL_SET_CONTEXT_ARCHITECTURE:
                state_dim = int(self.actionQResidualStateDim)
                action_dim = int(self.actionQResidualActionDim)
                rank = int(self.actionQResidualRank)
                if state_dim <= 0 or action_dim <= 0 or rank <= 0:
                    raise ValueError("action-Q residual legal-set critic requires positive state/action/rank dimensions")
                if len(self.actionQResidualStateW) != rank or len(self.actionQResidualStateB) != rank:
                    raise ValueError("action-Q residual legal-set state projection shape mismatch")
                if len(self.actionQResidualActionW) != rank:
                    raise ValueError("action-Q residual legal-set action projection shape mismatch")
                expected_context_dim = 6 * rank + 4
                if int(self.actionQResidualFeatureDim) != expected_context_dim:
                    raise ValueError("action-Q residual legal-set context feature dimension mismatch")
                if len(self.actionQResidualW) != rank * expected_context_dim:
                    raise ValueError("action-Q residual legal-set context projection shape mismatch")
                if len(self.actionQResidualOutputW) != rank:
                    raise ValueError("action-Q residual legal-set output weight shape mismatch")
                for row in self.actionQResidualStateW:
                    if len(row) != state_dim:
                        raise ValueError("action-Q residual legal-set state input dimension mismatch")
                for row in self.actionQResidualActionW:
                    if len(row) != action_dim:
                        raise ValueError("action-Q residual legal-set action input dimension mismatch")
            elif architecture == ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE:
                state_dim = int(self.actionQResidualStateDim)
                action_dim = int(self.actionQResidualActionDim)
                rank = int(self.actionQResidualRank)
                if state_dim <= 0 or action_dim <= 0 or rank <= 0:
                    raise ValueError("action-Q residual pairwise legal-set critic requires positive state/action/rank dimensions")
                if len(self.actionQResidualStateW) != rank or len(self.actionQResidualStateB) != rank:
                    raise ValueError("action-Q residual pairwise legal-set state projection shape mismatch")
                if len(self.actionQResidualActionW) != rank:
                    raise ValueError("action-Q residual pairwise legal-set action projection shape mismatch")
                expected_context_dim = 8 * rank + 5
                if int(self.actionQResidualFeatureDim) != expected_context_dim:
                    raise ValueError("action-Q residual pairwise legal-set context feature dimension mismatch")
                if len(self.actionQResidualW) != rank * expected_context_dim:
                    raise ValueError("action-Q residual pairwise legal-set context projection shape mismatch")
                if len(self.actionQResidualOutputW) != rank:
                    raise ValueError("action-Q residual pairwise legal-set output weight shape mismatch")
                for row in self.actionQResidualStateW:
                    if len(row) != state_dim:
                        raise ValueError("action-Q residual pairwise legal-set state input dimension mismatch")
                for row in self.actionQResidualActionW:
                    if len(row) != action_dim:
                        raise ValueError("action-Q residual pairwise legal-set action input dimension mismatch")
            elif self.actionQResidualW:
                if len(self.actionQResidualW) != int(self.actionQResidualFeatureDim):
                    raise ValueError("legacy action-Q residual linear feature dimension mismatch")
            else:
                raise ValueError(f"unknown action-Q residual architecture: {self.actionQResidualArchitecture!r}")
        q_backed_mode = _normalize_q_backed_actor_residual_mode(self.qBackedActorResidualMode)
        if q_backed_mode != Q_BACKED_ACTOR_RESIDUAL_DISABLED:
            if str(self.actionQResidualMode or "disabled").strip().lower() in {"", "disabled", "none", "off"}:
                raise ValueError("q-backed actor residual mode requires an exported action-Q residual critic")
            if str(self.actionQResidualArchitecture or "").strip().lower() not in {
                ACTION_Q_RESIDUAL_DUELING_ARCHITECTURE,
                ACTION_Q_RESIDUAL_MLP_ARCHITECTURE,
                ACTION_Q_RESIDUAL_LEGAL_SET_CONTEXT_ARCHITECTURE,
                ACTION_Q_RESIDUAL_FULL_CROSS_ARCHITECTURE,
                ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE,
            }:
                raise ValueError("q-backed actor residual mode requires a supported action-Q residual critic")

    def score_row(self, row: Mapping[str, Any]) -> list[float | None]:
        self.validate_shape()
        mask = _mask(row)
        enabled_slots = [slot for slot, enabled in enumerate(mask) if enabled]
        if not enabled_slots:
            return [None for _slot in mask]
        if self._recurrent_enabled():
            return self._score_row_recurrent_python(row, mask=mask)
        try:
            import numpy as np
        except ImportError:
            return self._score_row_python(row, mask=mask)
        weight_1, bias_1, weight_2 = self._numpy_weights(np)
        parts = _ygo_row_feature_parts(row, scorer=self)
        state_vector = _ygo_state_vector_from_parts(parts)
        condition_vector = self._state_action_condition_vector(row, state_vector)
        x = np.asarray(
            [_ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts) for slot in enabled_slots],
            dtype=np.float32,
        )
        hidden = np.maximum(0.0, x @ weight_1.T + bias_1)
        scored = hidden @ weight_2 + np.float32(self.b2)
        residual_weight = self._numpy_decision_residual_weight(np, row)
        if residual_weight is not None:
            scored = scored + x @ residual_weight
        if self._state_action_interaction_enabled():
            signature_indices = np.asarray(
                [
                    self._state_action_signature_index(row, int(slot))
                    if self._state_action_signature_index(row, int(slot)) is not None
                    else -1
                    for slot in enabled_slots
                ],
                dtype=np.int64,
            )
            scored = scored + self._state_action_interaction_scores_numpy(
                np,
                x,
                np.asarray([condition_vector for _slot in enabled_slots], dtype=np.float32),
                signature_indices,
            )
        if self._q_backed_actor_residual_enabled():
            scored = scored + self._q_backed_actor_residual_scores_numpy(
                np,
                x,
                np.asarray([condition_vector for _slot in enabled_slots], dtype=np.float32),
            )
        scored = scored * np.float32(self._runtime_aux_output_scale())
        scores: list[float | None] = [None for _slot in mask]
        for slot, score in zip(enabled_slots, scored, strict=True):
            scores[slot] = float(score)
        return self._center_legal_scores(scores)

    def _numpy_weights(self, np_module: Any) -> tuple[Any, Any, Any]:
        cache = self._numpyWeightCache
        if cache is None:
            cache = (
                np_module.asarray(self.w1, dtype=np_module.float32),
                np_module.asarray(self.b1, dtype=np_module.float32),
                np_module.asarray(self.w2, dtype=np_module.float32),
            )
            self._numpyWeightCache = cache
        return cache

    def _numpy_decision_residual_weight(self, np_module: Any, row: Mapping[str, Any]) -> Any | None:
        if not self._decision_residual_enabled():
            return None
        cache = self._decisionResidualNumpyWeightCache
        if cache is None:
            cache = {
                _decision_residual_key_from_text(key): np_module.asarray(values, dtype=np_module.float32)
                for key, values in (self.decisionResidualWeights or {}).items()
                if len(values) == int(self.inputDim)
            }
            self._decisionResidualNumpyWeightCache = cache
        return cache.get(_decision_residual_key_for_row(row))

    def _decision_residual_score(self, row: Mapping[str, Any], vector: Sequence[float]) -> float:
        if not self._decision_residual_enabled():
            return 0.0
        weights = (self.decisionResidualWeights or {}).get(_decision_residual_key_for_row(row))
        if weights is None:
            return 0.0
        return float(sum(float(weight) * float(value) for weight, value in zip(weights, vector, strict=True)))

    def _state_action_base_action_vector(self, vector: Sequence[float]) -> list[float]:
        prefix_dim = len(self.globalFeatureNames) + len(self.historyFeatureNames)
        action_dim = len(self.actionFeatureNames)
        card_dim = len(self.cardFeatureNames)
        action_start = prefix_dim
        action_end = action_start + action_dim
        pooled_end = action_end + card_dim
        source_end = pooled_end + card_dim
        values = list(vector)
        action_vector = (
            values[action_start:action_end]
            + values[pooled_end:source_end]
            + values[source_end : source_end + card_dim]
        )
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "prior_free_legal_ranker_v1",
            "prior_free_recurrent_legal_ranker_v1",
        }:
            mask = _state_action_prior_free_action_mask_values(self.actionFeatureNames, len(self.cardFeatureNames))
            action_vector = [
                float(value) * float(mask_value)
                for value, mask_value in zip(action_vector, mask, strict=False)
            ]
        return action_vector

    def _state_action_interaction_action_vector(
        self,
        vector: Sequence[float],
        legal_mean_action_vector: Sequence[float] | None = None,
    ) -> list[float]:
        action_vector = self._state_action_base_action_vector(vector)
        if _state_action_mode_uses_legal_set_context(self.stateActionInteractionMode):
            mean_values = (
                [float(value) for value in legal_mean_action_vector]
                if legal_mean_action_vector is not None
                else [0.0 for _value in action_vector]
            )
            action_vector = action_vector + [
                float(value) - float(mean)
                for value, mean in zip(action_vector, mean_values, strict=False)
            ]
        return action_vector

    def _state_action_condition_vector(
        self,
        row: Mapping[str, Any],
        state_vector: Sequence[float],
        recurrent_context: Sequence[float] | None = None,
    ) -> list[float]:
        state_values = [float(value) for value in state_vector]
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "signature_full_cross_delta_v1":
            centered_values = [
                (2.0 * float(value) - 1.0) if 0.0 <= float(value) <= 1.0 else float(value)
                for value in state_vector
            ]
            state_values = [0.0 for _value in state_values] + centered_values
        names = [str(value) for value in list(self.stateActionConditionDomainNames or [])]
        if _state_action_mode_uses_recurrent_context(self.stateActionInteractionMode):
            if recurrent_context is None:
                recurrent_context = self._runtime_recurrent_context(row) + self._recurrent_domain_vector(row)
            state_values += [float(value) for value in recurrent_context]
        if not names:
            condition_values = state_values
        else:
            label = _outcome_policy_coarse_bucket_label(_outcome_policy_coarse_bucket_key(row))
            condition_values = state_values + [
                1.0 if str(name) == str(label) else 0.0
                for name in names
            ]
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "prior_free_legal_ranker_v1",
            "prior_free_recurrent_legal_ranker_v1",
        }:
            center = [float(value) for value in list(self.stateActionStateCenter or [])]
            if len(center) == len(condition_values):
                condition_values = [
                    float(value) - float(center_value)
                    for value, center_value in zip(condition_values, center, strict=True)
                ]
        return condition_values

    def _state_action_signature_index(self, row: Mapping[str, Any], slot: int) -> int | None:
        if not self.stateActionSignatureNames:
            return None
        signature = _state_action_signature_for_slot(row, int(slot))
        try:
            return self.stateActionSignatureNames.index(signature)
        except ValueError:
            return None

    def _state_action_interaction_score(
        self,
        vector: Sequence[float],
        state_vector: Sequence[float],
        *,
        row: Mapping[str, Any] | None = None,
        slot: int | None = None,
        legal_mean_action_vector: Sequence[float] | None = None,
    ) -> float:
        if not self._state_action_interaction_enabled():
            return 0.0
        rank = max(1, int(self.stateActionInteractionRank))
        mode = _normalize_state_action_interaction_mode(self.stateActionInteractionMode)
        action_vector = self._state_action_interaction_action_vector(
            vector,
            legal_mean_action_vector=legal_mean_action_vector,
        )
        if mode == "signature_mlp_delta_v1":
            if row is None or slot is None:
                return 0.0
            index = self._state_action_signature_index(row, int(slot))
            if index is None or int(index) >= len(self.stateActionSignatureW):
                return 0.0
            input_vector = list(state_vector) + list(action_vector)
            norm = math.sqrt(sum(float(value) * float(value) for value in input_vector))
            if norm > 1.0e-8:
                input_vector = [float(value) / norm for value in input_vector]
            hidden = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, input_vector, strict=True)))
                for weights, bias in zip(self.stateActionStateW, self.stateActionStateB, strict=True)
            ]
            return float(
                sum(
                    float(weight) * float(value)
                    for weight, value in zip(self.stateActionSignatureW[int(index)], hidden, strict=True)
                )
            ) / math.sqrt(rank)
        if mode == "signature_low_rank_delta_v1":
            if row is None or slot is None:
                return 0.0
            index = self._state_action_signature_index(row, int(slot))
            if index is None or int(index) >= len(self.stateActionSignatureW):
                return 0.0
            state_proj = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                for weights, bias in zip(self.stateActionStateW, self.stateActionStateB, strict=True)
            ]
            action_proj = [
                float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
                for weights, bias in zip(self.stateActionActionW, self.stateActionActionB, strict=True)
            ]
            active_score = float(
                sum(
                    float(readout) * float(left) * float(right)
                    for readout, left, right in zip(self.stateActionSignatureW[int(index)], state_proj, action_proj, strict=True)
                )
            )
            if self.stateActionReferenceSignatureW:
                reference_state_proj = [
                    math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                    for weights, bias in zip(self.stateActionReferenceStateW, self.stateActionReferenceStateB, strict=True)
                ]
                reference_action_proj = [
                    float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
                    for weights, bias in zip(self.stateActionReferenceActionW, self.stateActionReferenceActionB, strict=True)
                ]
                reference_score = float(
                    sum(
                        float(readout) * float(left) * float(right)
                        for readout, left, right in zip(
                            self.stateActionReferenceSignatureW[int(index)],
                            reference_state_proj,
                            reference_action_proj,
                            strict=True,
                        )
                    )
                )
                active_score -= reference_score
            return active_score / math.sqrt(rank)
        if mode == "signature_full_cross_delta_v1":
            if row is None or slot is None:
                return 0.0
            index = self._state_action_signature_index(row, int(slot))
            if index is None or int(index) >= len(self.stateActionSignatureCrossW):
                return 0.0
            state_norm = math.sqrt(sum(float(value) * float(value) for value in state_vector))
            action_norm = math.sqrt(sum(float(value) * float(value) for value in action_vector))
            scaled_state = (
                [float(value) / state_norm for value in state_vector]
                if state_norm > 1.0e-8
                else [float(value) for value in state_vector]
            )
            scaled_action = (
                [float(value) / action_norm for value in action_vector]
                if action_norm > 1.0e-8
                else [float(value) for value in action_vector]
            )
            matrix = self.stateActionSignatureCrossW[int(index)]
            projected = [
                sum(float(weight) * float(value) for weight, value in zip(column, scaled_state, strict=True))
                for column in zip(*matrix, strict=True)
            ]
            active_score = float(sum(left * right for left, right in zip(projected, scaled_action, strict=True)))
            if self.stateActionReferenceSignatureCrossW:
                reference_matrix = self.stateActionReferenceSignatureCrossW[int(index)]
                reference_projected = [
                    sum(float(weight) * float(value) for weight, value in zip(column, scaled_state, strict=True))
                    for column in zip(*reference_matrix, strict=True)
                ]
                active_score -= float(sum(left * right for left, right in zip(reference_projected, scaled_action, strict=True)))
            return active_score
        if mode == "signature_state_linear_v1":
            if row is None or slot is None:
                return 0.0
            index = self._state_action_signature_index(row, int(slot))
            if index is None or int(index) >= len(self.stateActionSignatureW):
                return 0.0
            signature_vector = list(state_vector) + list(action_vector)
            state_norm = math.sqrt(sum(float(value) * float(value) for value in signature_vector))
            scaled_state = (
                [float(value) / state_norm for value in signature_vector]
                if state_norm > 1.0e-8
                else [float(value) for value in signature_vector]
            )
            return float(
                sum(
                    float(weight) * float(value)
                    for weight, value in zip(self.stateActionSignatureW[int(index)], scaled_state, strict=True)
                )
            )
        if mode in {"full_cross_v1", "full_cross_recurrent_v1"}:
            if not self.stateActionCrossW:
                return 0.0
            projected = [
                sum(float(weight) * float(value) for weight, value in zip(row, state_vector, strict=True))
                for row in zip(*self.stateActionCrossW, strict=True)
            ]
            return float(sum(left * right for left, right in zip(projected, action_vector, strict=True)))
        if mode in {"mlp_refdelta_v1", "mlp_recurrent_refdelta_v1"}:
            input_vector = list(state_vector) + list(action_vector)
            norm = math.sqrt(sum(float(value) * float(value) for value in input_vector))
            if norm > 1.0e-8:
                input_vector = [float(value) / norm for value in input_vector]
            hidden = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, input_vector, strict=True)))
                for weights, bias in zip(self.stateActionStateW, self.stateActionStateB, strict=True)
            ]
            reference_hidden = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, input_vector, strict=True)))
                for weights, bias in zip(self.stateActionReferenceStateW, self.stateActionReferenceStateB, strict=True)
            ]
            current_score = sum(
                float(weight) * float(value)
                for weight, value in zip(self.stateActionOutputW, hidden, strict=True)
            )
            reference_score = sum(
                float(weight) * float(value)
                for weight, value in zip(self.stateActionReferenceOutputW, reference_hidden, strict=True)
            )
            return float(current_score - reference_score) / math.sqrt(rank)
        if mode in {
            "prior_free_legal_ranker_v1",
            "prior_free_recurrent_legal_ranker_v1",
            "legal_set_context_ranker_v1",
            "legal_set_recurrent_context_ranker_v1",
        }:
            state_proj = [
                math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                for weights in self.stateActionStateW
            ]
            action_proj = [
                sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
                for weights in self.stateActionActionW
            ]
            active_score = float(
                sum(
                    float(weight) * float(left) * float(right)
                    for weight, left, right in zip(self.stateActionOutputW, state_proj, action_proj, strict=True)
                )
            )
            if self.stateActionReferenceStateW and self.stateActionReferenceActionW and self.stateActionReferenceOutputW:
                reference_state_proj = [
                    math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                    for weights in self.stateActionReferenceStateW
                ]
                reference_action_proj = [
                    sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
                    for weights in self.stateActionReferenceActionW
                ]
                active_score -= float(
                    sum(
                        float(weight) * float(left) * float(right)
                        for weight, left, right in zip(
                            self.stateActionReferenceOutputW,
                            reference_state_proj,
                            reference_action_proj,
                            strict=True,
                        )
                    )
                )
            return active_score / math.sqrt(rank)
        state_proj = [
            math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
            for weights, bias in zip(self.stateActionStateW, self.stateActionStateB, strict=True)
        ]
        action_proj = [
            float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
            for weights, bias in zip(self.stateActionActionW, self.stateActionActionB, strict=True)
        ]
        products = [left * right for left, right in zip(state_proj, action_proj, strict=True)]
        normalized_state_action_mode = _normalize_state_action_interaction_mode(self.stateActionInteractionMode)
        if normalized_state_action_mode in {
            "low_rank_v2",
            "legal_set_delta_ranker_v1",
        }:
            products = [
                product * float(weight)
                for product, weight in zip(products, self.stateActionOutputW, strict=True)
            ]
        if normalized_state_action_mode in {"low_rank_v3", "legal_set_delta_ranker_v1"}:
            reference_state_proj = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                for weights, bias in zip(self.stateActionReferenceStateW, self.stateActionReferenceStateB, strict=True)
            ]
            reference_action_proj = [
                float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True))
                for weights, bias in zip(self.stateActionReferenceActionW, self.stateActionReferenceActionB, strict=True)
            ]
            reference_products = [
                left * right for left, right in zip(reference_state_proj, reference_action_proj, strict=True)
            ]
            if normalized_state_action_mode == "legal_set_delta_ranker_v1":
                reference_products = [
                    product * float(weight)
                    for product, weight in zip(reference_products, self.stateActionReferenceOutputW, strict=True)
                ]
            products = [
                product - reference_product
                for product, reference_product in zip(products, reference_products, strict=True)
            ]
        return float(sum(products)) / math.sqrt(rank)

    def _score_row_python(self, row: Mapping[str, Any], *, mask: list[bool] | None = None) -> list[float | None]:
        scores: list[float | None] = []
        parts = _ygo_row_feature_parts(row, scorer=self)
        state_vector = _ygo_state_vector_from_parts(parts)
        condition_vector = self._state_action_condition_vector(row, state_vector)
        legal_mean_action_vector = None
        if _state_action_mode_uses_legal_set_context(self.stateActionInteractionMode):
            legal_vectors = [
                self._state_action_base_action_vector(
                    _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
                )
                for slot, enabled in enumerate(mask if mask is not None else _mask(row))
                if enabled
            ]
            if legal_vectors:
                legal_mean_action_vector = [
                    sum(float(values[index]) for values in legal_vectors) / float(len(legal_vectors))
                    for index in range(len(legal_vectors[0]))
                ]
        for slot, enabled in enumerate(mask if mask is not None else _mask(row)):
            if not enabled:
                scores.append(None)
                continue
            vector = _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
            hidden = [
                max(0.0, float(bias) + sum(float(weight) * value for weight, value in zip(weights, vector, strict=True)))
                for weights, bias in zip(self.w1, self.b1, strict=True)
            ]
            raw_score = float(self.b2) + sum(float(weight) * value for weight, value in zip(self.w2, hidden, strict=True))
            raw_score += self._decision_residual_score(row, vector)
            raw_score += self._state_action_interaction_score(
                vector,
                condition_vector,
                row=row,
                slot=slot,
                legal_mean_action_vector=legal_mean_action_vector,
            )
            scores.append(raw_score * self._runtime_aux_output_scale())
        if self._q_backed_actor_residual_enabled():
            active_slots = [
                slot
                for slot, enabled in enumerate(mask if mask is not None else _mask(row))
                if enabled
            ]
            active_vectors = [
                _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
                for slot in active_slots
            ]
            q_residuals = self._q_backed_actor_residual_scores_for_row(
                active_vectors,
                condition_vector,
                legal_mean_action_vector=legal_mean_action_vector,
                broad_prior=[
                    float(scores[slot]) / max(1.0e-6, float(self._runtime_aux_output_scale()))
                    for slot in active_slots
                    if scores[slot] is not None
                ],
            )
            residual_by_slot = {slot: q_residuals[index] for index, slot in enumerate(active_slots)}
            scores = [
                None
                if score is None
                else float(score) + float(residual_by_slot.get(slot, 0.0)) * self._runtime_aux_output_scale()
                for slot, score in enumerate(scores)
            ]
        return self._center_legal_scores(scores)

    def score_rows(self, rows: list[Mapping[str, Any]]) -> list[list[float | None]]:
        return [self.score_row(row) for row in rows]

    def score_rows_batched(
        self,
        rows: list[Mapping[str, Any]],
        *,
        batch_size: int = 512,
    ) -> list[list[float | None]]:
        if not rows:
            return []
        if self._recurrent_enabled():
            return self._score_rows_batched_recurrent(rows, batch_size=batch_size)
        self.validate_shape()
        try:
            import numpy as np
        except ImportError:
            return self.score_rows(rows)

        weight_1, bias_1, weight_2 = self._numpy_weights(np)
        bounded_batch = max(1, int(batch_size))
        out: list[list[float | None]] = []
        for start in range(0, len(rows), bounded_batch):
            batch = rows[start : start + bounded_batch]
            masks = [_mask(row) for row in batch]
            flat_vectors: list[list[float]] = []
            flat_states: list[list[float]] = []
            flat_signature_indices: list[int] = []
            flat_positions: list[tuple[int, int]] = []
            for row_index, row in enumerate(batch):
                parts = _ygo_row_feature_parts(row, scorer=self)
                state_vector = _ygo_state_vector_from_parts(parts)
                self._runtimeStateValueCache[id(row)] = self._state_value_from_state_vector(row, state_vector)
                condition_vector = self._state_action_condition_vector(row, state_vector)
                for slot, enabled in enumerate(masks[row_index]):
                    if not enabled:
                        continue
                    flat_positions.append((row_index, slot))
                    flat_vectors.append(_ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts))
                    flat_states.append(condition_vector)
                    signature_index = self._state_action_signature_index(row, slot)
                    flat_signature_indices.append(int(signature_index) if signature_index is not None else -1)
            row_scores_by_index: list[list[float | None]] = [[None for _slot in mask] for mask in masks]
            if flat_vectors:
                x = np.asarray(flat_vectors, dtype=np.float32)
                hidden = np.maximum(0.0, x @ weight_1.T + bias_1)
                scores = hidden @ weight_2 + np.float32(self.b2)
                if self._decision_residual_enabled():
                    residual_values: list[float] = []
                    for flat_index, (row_index, _slot) in enumerate(flat_positions):
                        residual_weight = self._numpy_decision_residual_weight(np, batch[row_index])
                        residual_values.append(
                            float(x[flat_index] @ residual_weight)
                            if residual_weight is not None
                            else 0.0
                        )
                    scores = scores + np.asarray(residual_values, dtype=np.float32)
                if self._state_action_interaction_enabled():
                    broad_prior_scores = scores.copy()
                    scores = scores + self._state_action_interaction_scores_numpy(
                        np,
                        x,
                        np.asarray(flat_states, dtype=np.float32),
                        np.asarray(flat_signature_indices, dtype=np.int64),
                        group_indices=np.asarray([row_index for row_index, _slot in flat_positions], dtype=np.int64),
                    )
                    if self._q_backed_actor_residual_enabled():
                        scores = scores + self._q_backed_actor_residual_scores_numpy(
                            np,
                            x,
                            np.asarray(flat_states, dtype=np.float32),
                            group_indices=np.asarray([row_index for row_index, _slot in flat_positions], dtype=np.int64),
                            broad_prior=broad_prior_scores,
                        )
                elif self._q_backed_actor_residual_enabled():
                    scores = scores + self._q_backed_actor_residual_scores_numpy(
                        np,
                        x,
                        np.asarray(flat_states, dtype=np.float32),
                        group_indices=np.asarray([row_index for row_index, _slot in flat_positions], dtype=np.int64),
                        broad_prior=scores.copy(),
                    )
                scores = scores * np.float32(self._runtime_aux_output_scale())
                for (row_index, slot), score in zip(flat_positions, scores, strict=True):
                    row_scores_by_index[row_index][slot] = float(score)
            out.extend(self._center_legal_scores(row_scores) for row_scores in row_scores_by_index)
        return out

    def _numpy_recurrent_weights(self, np_module: Any) -> tuple[Any, Any, Any]:
        cache = self._recurrentNumpyWeightCache
        if cache is None:
            cache = (
                np_module.asarray(self.recurrentPolicyW1, dtype=np_module.float32),
                np_module.asarray(self.recurrentPolicyB1, dtype=np_module.float32),
                np_module.asarray(self.recurrentPolicyW2, dtype=np_module.float32),
            )
            self._recurrentNumpyWeightCache = cache
        return cache

    def _numpy_recurrent_gru_weights(self, np_module: Any) -> tuple[Any, Any, Any, Any]:
        cache = self._recurrentNumpyGruWeightCache
        if cache is None:
            cache = (
                np_module.asarray(self.recurrentGruWeightIh, dtype=np_module.float32),
                np_module.asarray(self.recurrentGruWeightHh, dtype=np_module.float32),
                np_module.asarray(self.recurrentGruBiasIh, dtype=np_module.float32),
                np_module.asarray(self.recurrentGruBiasHh, dtype=np_module.float32),
            )
            self._recurrentNumpyGruWeightCache = cache
        return cache

    def _numpy_state_action_interaction_weights(self, np_module: Any) -> tuple[Any, Any, Any, Any, Any, Any, Any, Any, Any, Any, Any, Any, Any, Any, Any]:
        cache = self._stateActionInteractionNumpyWeightCache
        if cache is None:
            cache = (
                np_module.asarray(self.stateActionStateW, dtype=np_module.float32),
                np_module.asarray(self.stateActionStateB, dtype=np_module.float32),
                np_module.asarray(self.stateActionActionW, dtype=np_module.float32),
                np_module.asarray(self.stateActionActionB, dtype=np_module.float32),
                np_module.asarray(self.stateActionOutputW, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceStateW, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceStateB, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceActionW, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceActionB, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceOutputW, dtype=np_module.float32),
                np_module.asarray(self.stateActionCrossW, dtype=np_module.float32),
                np_module.asarray(self.stateActionSignatureW, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceSignatureW, dtype=np_module.float32),
                np_module.asarray(self.stateActionSignatureCrossW, dtype=np_module.float32),
                np_module.asarray(self.stateActionReferenceSignatureCrossW, dtype=np_module.float32),
            )
            self._stateActionInteractionNumpyWeightCache = cache
        return cache

    def _q_backed_actor_residual_enabled(self) -> bool:
        return (
            _normalize_q_backed_actor_residual_mode(self.qBackedActorResidualMode)
            == Q_BACKED_ACTOR_RESIDUAL_MEAN_LEGAL_ACTION_Q
        )

    def _numpy_action_q_residual_weights(self, np_module: Any) -> tuple[Any, Any, Any, Any]:
        cache = self._actionQResidualNumpyWeightCache
        if cache is None:
            cache = (
                np_module.asarray(self.actionQResidualStateW, dtype=np_module.float32),
                np_module.asarray(self.actionQResidualStateB, dtype=np_module.float32),
                np_module.asarray(self.actionQResidualActionW, dtype=np_module.float32),
                np_module.asarray(self.actionQResidualOutputW, dtype=np_module.float32),
            )
            self._actionQResidualNumpyWeightCache = cache
        return cache

    def _action_q_raw_score(
        self,
        vector: Sequence[float],
        state_vector: Sequence[float],
        *,
        legal_mean_action_vector: Sequence[float] | None = None,
    ) -> float:
        if not self._q_backed_actor_residual_enabled():
            return 0.0
        architecture = str(self.actionQResidualArchitecture or "").strip().lower()
        action_vector = self._state_action_interaction_action_vector(
            vector,
            legal_mean_action_vector=legal_mean_action_vector,
        )
        if architecture == ACTION_Q_RESIDUAL_MLP_ARCHITECTURE:
            state_action_vector = list(state_vector) + list(action_vector)
            hidden = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_action_vector, strict=True)))
                for weights, bias in zip(self.actionQResidualStateW, self.actionQResidualStateB, strict=True)
            ]
            return float(self.actionQResidualB) + float(
                sum(
                    float(weight) * float(value)
                    for weight, value in zip(self.actionQResidualOutputW, hidden, strict=True)
                )
            )
        if architecture == ACTION_Q_RESIDUAL_FULL_CROSS_ARCHITECTURE:
            state_proj = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                for weights, bias in zip(self.actionQResidualStateW, self.actionQResidualStateB, strict=True)
            ]
            action_proj = [
                math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True)))
                for weights in self.actionQResidualActionW
            ]
            cross = [
                float(left) * float(right)
                for left in state_proj
                for right in action_proj
            ]
            scale = 1.0 / math.sqrt(max(1, int(len(self.actionQResidualOutputW))))
            return float(
                sum(
                    float(weight) * float(value)
                    for weight, value in zip(self.actionQResidualOutputW, cross, strict=True)
                )
            ) * float(scale)
        if architecture != ACTION_Q_RESIDUAL_DUELING_ARCHITECTURE:
            return 0.0
        state_proj = [
            math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
            for weights, bias in zip(self.actionQResidualStateW, self.actionQResidualStateB, strict=True)
        ]
        action_proj = [
            math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True)))
            for weights in self.actionQResidualActionW
        ]
        scale = 1.0 / math.sqrt(max(1, int(len(self.actionQResidualOutputW))))
        return float(
            sum(
                float(weight) * float(left) * float(right)
                for weight, left, right in zip(self.actionQResidualOutputW, state_proj, action_proj, strict=True)
            )
        ) * float(scale)

    def _q_backed_actor_residual_scores_for_row(
        self,
        vectors: Sequence[Sequence[float]],
        state_vector: Sequence[float],
        *,
        legal_mean_action_vector: Sequence[float] | None = None,
        broad_prior: Sequence[float] | None = None,
    ) -> list[float]:
        if not self._q_backed_actor_residual_enabled() or not vectors:
            return [0.0 for _vector in vectors]
        architecture = str(self.actionQResidualArchitecture or "").strip().lower()
        if architecture in ACTION_Q_RESIDUAL_LEGAL_CONTEXT_ARCHITECTURES:
            action_vectors = [
                self._state_action_interaction_action_vector(
                    vector,
                    legal_mean_action_vector=legal_mean_action_vector,
                )
                for vector in vectors
            ]
            state_proj = [
                math.tanh(float(bias) + sum(float(weight) * float(value) for weight, value in zip(weights, state_vector, strict=True)))
                for weights, bias in zip(self.actionQResidualStateW, self.actionQResidualStateB, strict=True)
            ]
            action_proj_rows = [
                [
                    math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, action_vector, strict=True)))
                    for weights in self.actionQResidualActionW
                ]
                for action_vector in action_vectors
            ]
            rank = int(self.actionQResidualRank)
            count = max(1, len(action_proj_rows))
            mean_action = [
                sum(float(row[index]) for row in action_proj_rows) / float(count)
                for index in range(rank)
            ]
            max_action = [
                max(float(row[index]) for row in action_proj_rows)
                for index in range(rank)
            ]
            broad_values = [float(value) for value in broad_prior] if broad_prior is not None else [0.0 for _ in vectors]
            mean_broad = sum(broad_values) / float(max(1, len(broad_values)))
            max_broad = max(broad_values) if broad_values else 0.0
            count_feature = math.log1p(float(count)) / math.log(64.0)
            if architecture == ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE:
                context_dim = 8 * rank + 5
            else:
                context_dim = 6 * rank + 4
            context_rows = [
                self.actionQResidualW[start : start + context_dim]
                for start in range(0, len(self.actionQResidualW), context_dim)
            ]
            raw_scores: list[float] = []
            min_broad = min(broad_values) if broad_values else 0.0
            for index, (action_proj, broad_value) in enumerate(zip(action_proj_rows, broad_values, strict=True)):
                if architecture == ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE:
                    competitor_count = max(1, count - 1)
                    if count > 1:
                        other_mean_action = [
                            (sum(float(row[dim]) for row in action_proj_rows) - float(action_proj[dim])) / float(competitor_count)
                            for dim in range(rank)
                        ]
                        pair_abs_mean_delta = [
                            sum(abs(float(action_proj[dim]) - float(row[dim])) for row_i, row in enumerate(action_proj_rows) if row_i != index)
                            / float(competitor_count)
                            for dim in range(rank)
                        ]
                        other_mean_broad = (sum(broad_values) - float(broad_value)) / float(competitor_count)
                    else:
                        other_mean_action = [float(value) for value in action_proj]
                        pair_abs_mean_delta = [0.0 for _ in range(rank)]
                        other_mean_broad = float(broad_value)
                    competitor_count_feature = math.log1p(float(max(0, count - 1))) / math.log(64.0)
                    features = (
                        state_proj
                        + action_proj
                        + [float(left) * float(right) for left, right in zip(state_proj, action_proj, strict=True)]
                        + [float(value) - float(mean_action[dim]) for dim, value in enumerate(action_proj)]
                        + mean_action
                        + max_action
                        + [float(value) - float(other_mean_action[dim]) for dim, value in enumerate(action_proj)]
                        + pair_abs_mean_delta
                        + [
                            float(broad_value) - float(other_mean_broad),
                            float(max_broad) - float(broad_value),
                            float(broad_value) - float(min_broad),
                            float(count_feature),
                            float(competitor_count_feature),
                        ]
                    )
                else:
                    features = (
                        state_proj
                        + action_proj
                        + [float(left) * float(right) for left, right in zip(state_proj, action_proj, strict=True)]
                        + [float(value) - float(mean_action[index]) for index, value in enumerate(action_proj)]
                        + [float(broad_value) - float(mean_broad)]
                        + mean_action
                        + max_action
                        + [float(mean_broad), float(max_broad), float(count_feature)]
                    )
                hidden = [
                    math.tanh(sum(float(weight) * float(value) for weight, value in zip(weights, features, strict=True)))
                    for weights in context_rows
                ]
                raw_scores.append(
                    float(self.actionQResidualB)
                    + sum(
                        float(weight) * float(value)
                        for weight, value in zip(self.actionQResidualOutputW, hidden, strict=True)
                    )
                )
            mean_score = sum(raw_scores) / float(len(raw_scores))
            return [float(value) - float(mean_score) for value in raw_scores]
        raw_scores = [
            self._action_q_raw_score(
                vector,
                state_vector,
                legal_mean_action_vector=legal_mean_action_vector,
            )
            for vector in vectors
        ]
        mean_score = sum(raw_scores) / float(len(raw_scores))
        return [float(value) - float(mean_score) for value in raw_scores]

    def _q_backed_actor_residual_scores_numpy(
        self,
        np_module: Any,
        x: Any,
        state_x: Any,
        *,
        group_indices: Any | None = None,
        broad_prior: Any | None = None,
    ) -> Any:
        if not self._q_backed_actor_residual_enabled():
            return np_module.zeros((x.shape[0],), dtype=np_module.float32)
        state_w, state_b, action_w, output_w = self._numpy_action_q_residual_weights(np_module)
        if int(state_w.size) == 0 or int(output_w.size) == 0:
            return np_module.zeros((x.shape[0],), dtype=np_module.float32)
        action_x = self._state_action_interaction_action_matrix(
            np_module,
            x,
            group_indices=group_indices,
        )
        architecture = str(self.actionQResidualArchitecture or "").strip().lower()
        if architecture == ACTION_Q_RESIDUAL_MLP_ARCHITECTURE:
            state_action_x = np_module.concatenate([state_x, action_x], axis=1)
            hidden = np_module.tanh(state_action_x @ state_w.T + state_b)
            q_raw = hidden @ output_w + np_module.float32(float(self.actionQResidualB))
        elif architecture in ACTION_Q_RESIDUAL_LEGAL_CONTEXT_ARCHITECTURES:
            if int(action_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_h = np_module.tanh(state_x @ state_w.T + state_b)
            action_h = np_module.tanh(action_x @ action_w.T)
            context_dim = (
                8 * int(self.actionQResidualRank) + 5
                if architecture == ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE
                else 6 * int(self.actionQResidualRank) + 4
            )
            context_w = np_module.asarray(self.actionQResidualW, dtype=np_module.float32).reshape(
                (int(self.actionQResidualRank), int(context_dim))
            )
            broad_values = (
                np_module.asarray(broad_prior, dtype=np_module.float32).reshape((-1,))
                if broad_prior is not None
                else np_module.zeros((x.shape[0],), dtype=np_module.float32)
            )
            q_raw = np_module.zeros((x.shape[0],), dtype=np_module.float32)
            groups = [0] if group_indices is None else sorted(set(int(value) for value in list(group_indices)))
            group_values = np_module.zeros((x.shape[0],), dtype=np_module.int64) if group_indices is None else group_indices
            rank = int(self.actionQResidualRank)
            for group in groups:
                mask = group_values == int(group)
                if not bool(mask.any()):
                    continue
                count = int(mask.sum())
                mean_action = action_h[mask].mean(axis=0)
                max_action = action_h[mask].max(axis=0)
                mean_broad = broad_values[mask].mean()
                max_broad = broad_values[mask].max()
                min_broad = broad_values[mask].min()
                count_feature = np_module.float32(math.log1p(float(count)) / math.log(64.0))
                repeated_state_h = state_h[mask]
                selected_action_h = action_h[mask]
                selected_broad = broad_values[mask]
                if architecture == ACTION_Q_RESIDUAL_PAIRWISE_LEGAL_SET_ARCHITECTURE:
                    if count > 1:
                        competitor_count = float(max(1, count - 1))
                        other_mean_action = (selected_action_h.sum(axis=0).reshape((1, rank)) - selected_action_h) / competitor_count
                        pair_abs_mean_delta = np_module.abs(
                            selected_action_h[:, None, :] - selected_action_h[None, :, :]
                        ).sum(axis=1) / competitor_count
                        other_mean_broad = (selected_broad.sum() - selected_broad) / competitor_count
                    else:
                        other_mean_action = selected_action_h
                        pair_abs_mean_delta = np_module.zeros_like(selected_action_h)
                        other_mean_broad = selected_broad
                    competitor_count_feature = np_module.float32(math.log1p(float(max(0, count - 1))) / math.log(64.0))
                    features = np_module.concatenate(
                        [
                            repeated_state_h,
                            selected_action_h,
                            repeated_state_h * selected_action_h,
                            selected_action_h - mean_action.reshape((1, rank)),
                            np_module.broadcast_to(mean_action.reshape((1, rank)), (count, rank)),
                            np_module.broadcast_to(max_action.reshape((1, rank)), (count, rank)),
                            selected_action_h - other_mean_action,
                            pair_abs_mean_delta,
                            (selected_broad - other_mean_broad).reshape((count, 1)),
                            (max_broad - selected_broad).reshape((count, 1)),
                            (selected_broad - min_broad).reshape((count, 1)),
                            np_module.full((count, 1), count_feature, dtype=np_module.float32),
                            np_module.full((count, 1), competitor_count_feature, dtype=np_module.float32),
                        ],
                        axis=1,
                    )
                else:
                    features = np_module.concatenate(
                        [
                            repeated_state_h,
                            selected_action_h,
                            repeated_state_h * selected_action_h,
                            selected_action_h - mean_action.reshape((1, rank)),
                            (selected_broad - mean_broad).reshape((count, 1)),
                            np_module.broadcast_to(mean_action.reshape((1, rank)), (count, rank)),
                            np_module.broadcast_to(max_action.reshape((1, rank)), (count, rank)),
                            np_module.full((count, 1), mean_broad, dtype=np_module.float32),
                            np_module.full((count, 1), max_broad, dtype=np_module.float32),
                            np_module.full((count, 1), count_feature, dtype=np_module.float32),
                        ],
                        axis=1,
                    )
                hidden = np_module.tanh(features @ context_w.T)
                q_raw[mask] = hidden @ output_w + np_module.float32(float(self.actionQResidualB))
        elif architecture == ACTION_Q_RESIDUAL_FULL_CROSS_ARCHITECTURE:
            if int(action_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_h = np_module.tanh(state_x @ state_w.T + state_b)
            action_h = np_module.tanh(action_x @ action_w.T)
            rank = int(self.actionQResidualRank)
            cross = (state_h[:, :, None] * action_h[:, None, :]).reshape((x.shape[0], rank * rank))
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(output_w.shape[0]))))
            q_raw = (cross @ output_w) * scale
        elif architecture == ACTION_Q_RESIDUAL_DUELING_ARCHITECTURE:
            if int(action_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_h = np_module.tanh(state_x @ state_w.T + state_b)
            action_h = np_module.tanh(action_x @ action_w.T)
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(output_w.shape[0]))))
            q_raw = (state_h * action_h * output_w).sum(axis=1) * scale
        else:
            return np_module.zeros((x.shape[0],), dtype=np_module.float32)
        if group_indices is None:
            return q_raw - (q_raw.mean() if int(q_raw.shape[0]) else np_module.float32(0.0))
        centered = np_module.zeros_like(q_raw)
        for group in sorted(set(int(value) for value in list(group_indices))):
            mask = group_indices == int(group)
            if bool(mask.any()):
                centered[mask] = q_raw[mask] - q_raw[mask].mean()
        return centered

    def _state_action_interaction_action_matrix(
        self,
        np_module: Any,
        x: Any,
        group_indices: Any | None = None,
    ) -> Any:
        prefix_dim = len(self.globalFeatureNames) + len(self.historyFeatureNames)
        action_dim = len(self.actionFeatureNames)
        card_dim = len(self.cardFeatureNames)
        action_start = prefix_dim
        action_end = action_start + action_dim
        pooled_end = action_end + card_dim
        source_end = pooled_end + card_dim
        action_x = np_module.concatenate(
            [
                x[:, action_start:action_end],
                x[:, pooled_end:source_end],
                x[:, source_end : source_end + card_dim],
            ],
            axis=1,
        )
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "prior_free_legal_ranker_v1",
            "prior_free_recurrent_legal_ranker_v1",
        }:
            mask = np_module.asarray(
                _state_action_prior_free_action_mask_values(self.actionFeatureNames, len(self.cardFeatureNames)),
                dtype=np_module.float32,
            )
            action_x = action_x * mask[None, :]
        if _state_action_mode_uses_legal_set_context(self.stateActionInteractionMode):
            if group_indices is None:
                mean_x = action_x.mean(axis=0, keepdims=True) if int(action_x.shape[0]) else action_x
                centered_x = action_x - mean_x
            else:
                centered_x = np_module.zeros_like(action_x)
                for group in sorted(set(int(value) for value in list(group_indices))):
                    mask = group_indices == int(group)
                    if bool(mask.any()):
                        centered_x[mask] = action_x[mask] - action_x[mask].mean(axis=0, keepdims=True)
            action_x = np_module.concatenate([action_x, centered_x], axis=1)
        return action_x

    def _state_action_interaction_scores_numpy(
        self,
        np_module: Any,
        x: Any,
        state_x: Any,
        signature_indices: Any | None = None,
        *,
        group_indices: Any | None = None,
    ) -> Any:
        (
            state_w,
            state_b,
            action_w,
            action_b,
            output_w,
            reference_state_w,
            reference_state_b,
            reference_action_w,
            reference_action_b,
            reference_output_w,
            cross_w,
            signature_w,
            reference_signature_w,
            signature_cross_w,
            reference_signature_cross_w,
        ) = self._numpy_state_action_interaction_weights(np_module)
        action_x = self._state_action_interaction_action_matrix(
            np_module,
            x,
            group_indices=group_indices,
        )
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "signature_mlp_delta_v1":
            if signature_indices is None or int(signature_w.size) == 0 or int(state_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            known = (signature_indices >= 0) & (signature_indices < signature_w.shape[0])
            safe_indices = np_module.maximum(signature_indices, 0)
            input_x = np_module.concatenate([state_x, action_x], axis=1)
            input_norm = np_module.linalg.norm(input_x, axis=1, keepdims=True)
            input_x = input_x / np_module.maximum(input_norm, np_module.float32(1.0e-8))
            hidden = np_module.tanh(input_x @ state_w.T + state_b)
            selected_w = signature_w[safe_indices] * known[:, None]
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
            return (selected_w * hidden).sum(axis=1) * scale
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "signature_low_rank_delta_v1":
            if signature_indices is None or int(signature_w.size) == 0 or int(state_w.size) == 0 or int(action_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            known = (signature_indices >= 0) & (signature_indices < signature_w.shape[0])
            safe_indices = np_module.maximum(signature_indices, 0)
            state_proj = np_module.tanh(state_x @ state_w.T + state_b)
            action_proj = action_x @ action_w.T + action_b
            selected_w = signature_w[safe_indices] * known[:, None]
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
            score = (selected_w * state_proj * action_proj).sum(axis=1)
            if (
                int(reference_signature_w.size) != 0
                and int(reference_state_w.size) != 0
                and int(reference_action_w.size) != 0
            ):
                reference_state_proj = np_module.tanh(state_x @ reference_state_w.T + reference_state_b)
                reference_action_proj = action_x @ reference_action_w.T + reference_action_b
                reference_selected_w = reference_signature_w[safe_indices] * known[:, None]
                score = score - (reference_selected_w * reference_state_proj * reference_action_proj).sum(axis=1)
            return score * scale
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "signature_full_cross_delta_v1":
            if signature_indices is None or int(signature_cross_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_norm = np_module.linalg.norm(state_x, axis=1, keepdims=True)
            action_norm = np_module.linalg.norm(action_x, axis=1, keepdims=True)
            scaled_state_x = state_x / np_module.maximum(state_norm, np_module.float32(1.0e-8))
            scaled_action_x = action_x / np_module.maximum(action_norm, np_module.float32(1.0e-8))
            scores = np_module.zeros((x.shape[0],), dtype=np_module.float32)
            max_signature = int(signature_cross_w.shape[0])
            for signature_index in range(max_signature):
                mask = signature_indices == signature_index
                if not bool(mask.any()):
                    continue
                projected = scaled_state_x[mask] @ signature_cross_w[signature_index]
                scores[mask] = (projected * scaled_action_x[mask]).sum(axis=1)
                if int(reference_signature_cross_w.size) != 0 and int(reference_signature_cross_w.shape[0]) > signature_index:
                    reference_projected = scaled_state_x[mask] @ reference_signature_cross_w[signature_index]
                    scores[mask] = scores[mask] - (reference_projected * scaled_action_x[mask]).sum(axis=1)
            return scores
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "signature_state_linear_v1":
            if signature_indices is None or int(signature_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            known = (signature_indices >= 0) & (signature_indices < signature_w.shape[0])
            safe_indices = np_module.maximum(signature_indices, 0)
            selected_w = signature_w[safe_indices] * known[:, None]
            signature_x = np_module.concatenate([state_x, action_x], axis=1)
            state_norm = np_module.linalg.norm(signature_x, axis=1, keepdims=True)
            scaled_signature = signature_x / np_module.maximum(state_norm, np_module.float32(1.0e-8))
            return (selected_w * scaled_signature).sum(axis=1)
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "prior_free_legal_ranker_v1",
            "prior_free_recurrent_legal_ranker_v1",
            "legal_set_context_ranker_v1",
            "legal_set_recurrent_context_ranker_v1",
        }:
            if int(state_w.size) == 0 or int(action_w.size) == 0 or int(output_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_proj = np_module.tanh(state_x @ state_w.T)
            action_proj = action_x @ action_w.T
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
            score = (state_proj * action_proj * output_w).sum(axis=1)
            if (
                int(reference_state_w.size) != 0
                and int(reference_action_w.size) != 0
                and int(reference_output_w.size) != 0
            ):
                reference_state_proj = np_module.tanh(state_x @ reference_state_w.T)
                reference_action_proj = action_x @ reference_action_w.T
                score = score - (reference_state_proj * reference_action_proj * reference_output_w).sum(axis=1)
            return score * scale
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "legal_set_delta_ranker_v1":
            if int(state_w.size) == 0 or int(action_w.size) == 0 or int(output_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            state_proj = np_module.tanh(state_x @ state_w.T + state_b)
            action_proj = action_x @ action_w.T + action_b
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
            score = (state_proj * action_proj * output_w).sum(axis=1)
            if (
                int(reference_state_w.size) != 0
                and int(reference_action_w.size) != 0
                and int(reference_output_w.size) != 0
            ):
                reference_state_proj = np_module.tanh(state_x @ reference_state_w.T + reference_state_b)
                reference_action_proj = action_x @ reference_action_w.T + reference_action_b
                score = score - (reference_state_proj * reference_action_proj * reference_output_w).sum(axis=1)
            return score * scale
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "full_cross_v1",
            "full_cross_recurrent_v1",
        }:
            if int(cross_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            return ((state_x @ cross_w) * action_x).sum(axis=1)
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) in {
            "mlp_refdelta_v1",
            "mlp_recurrent_refdelta_v1",
        }:
            if int(state_w.size) == 0 or int(output_w.size) == 0 or int(reference_state_w.size) == 0:
                return np_module.zeros((x.shape[0],), dtype=np_module.float32)
            input_x = np_module.concatenate([state_x, action_x], axis=1)
            input_norm = np_module.linalg.norm(input_x, axis=1, keepdims=True)
            input_x = input_x / np_module.maximum(input_norm, np_module.float32(1.0e-8))
            hidden = np_module.tanh(input_x @ state_w.T + state_b)
            reference_hidden = np_module.tanh(input_x @ reference_state_w.T + reference_state_b)
            scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
            return ((hidden * output_w) - (reference_hidden * reference_output_w)).sum(axis=1) * scale
        if int(state_w.size) == 0 or int(action_w.size) == 0:
            return np_module.zeros((x.shape[0],), dtype=np_module.float32)
        state_proj = np_module.tanh(state_x @ state_w.T + state_b)
        action_proj = action_x @ action_w.T + action_b
        products = state_proj * action_proj
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "low_rank_v2":
            products = products * output_w
        if _normalize_state_action_interaction_mode(self.stateActionInteractionMode) == "low_rank_v3":
            reference_state_proj = np_module.tanh(state_x @ reference_state_w.T + reference_state_b)
            reference_action_proj = action_x @ reference_action_w.T + reference_action_b
            products = products - (reference_state_proj * reference_action_proj)
        scale = np_module.float32(1.0 / math.sqrt(max(1, int(self.stateActionInteractionRank))))
        return products.sum(axis=1) * scale

    def _score_rows_batched_recurrent(
        self,
        rows: list[Mapping[str, Any]],
        *,
        batch_size: int = 512,
    ) -> list[list[float | None]]:
        self.validate_shape()
        try:
            import numpy as np
        except ImportError:
            return [self._score_row_recurrent_python(row, mask=_mask(row)) for row in rows]

        weight_1, bias_1, weight_2 = self._numpy_weights(np)
        recurrent_weight_1, recurrent_bias_1, recurrent_weight_2 = self._numpy_recurrent_weights(np)
        bounded_batch = max(1, int(batch_size))
        out: list[list[float | None]] = []
        for start in range(0, len(rows), bounded_batch):
            batch = rows[start : start + bounded_batch]
            masks = [_mask(row) for row in batch]
            contexts = [
                self._runtime_recurrent_context(row) + self._recurrent_domain_vector(row)
                for row in batch
            ]
            flat_vectors: list[list[float]] = []
            flat_states: list[list[float]] = []
            flat_contexts: list[list[float]] = []
            flat_positions: list[tuple[int, int]] = []
            for row_index, row in enumerate(batch):
                parts = _ygo_row_feature_parts(row, scorer=self)
                state_vector = _ygo_state_vector_from_parts(parts)
                self._runtimeStateValueCache[id(row)] = self._state_value_from_state_vector(
                    row,
                    state_vector,
                    recurrent_context=contexts[row_index],
                )
                condition_vector = self._state_action_condition_vector(row, state_vector)
                for slot, enabled in enumerate(masks[row_index]):
                    if not enabled:
                        continue
                    flat_positions.append((row_index, slot))
                    flat_vectors.append(_ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts))
                    flat_states.append(condition_vector)
                    flat_contexts.append(contexts[row_index])
            row_scores_by_index: list[list[float | None]] = [[None for _slot in mask] for mask in masks]
            if flat_vectors:
                x = np.asarray(flat_vectors, dtype=np.float32)
                hidden = np.maximum(0.0, x @ weight_1.T + bias_1)
                base_scores = hidden @ weight_2 + np.float32(self.b2)
                if recurrent_weight_1.size:
                    recurrent_x = np.concatenate(
                        [x, np.asarray(flat_contexts, dtype=np.float32)],
                        axis=1,
                    )
                    recurrent_hidden = np.maximum(0.0, recurrent_x @ recurrent_weight_1.T + recurrent_bias_1)
                    recurrent_scores = recurrent_hidden @ recurrent_weight_2 + np.float32(self.recurrentPolicyB2)
                else:
                    recurrent_scores = np.zeros_like(base_scores)
                scores = base_scores + recurrent_scores
                if self._decision_residual_enabled():
                    residual_values: list[float] = []
                    for flat_index, (row_index, _slot) in enumerate(flat_positions):
                        residual_weight = self._numpy_decision_residual_weight(np, batch[row_index])
                        residual_values.append(
                            float(x[flat_index] @ residual_weight)
                            if residual_weight is not None
                            else 0.0
                        )
                    scores = scores + np.asarray(residual_values, dtype=np.float32)
                if self._state_action_interaction_enabled():
                    flat_signature_indices = []
                    for row_index, slot in flat_positions:
                        index = self._state_action_signature_index(batch[row_index], int(slot))
                        flat_signature_indices.append(int(index) if index is not None else -1)
                    scores = scores + self._state_action_interaction_scores_numpy(
                        np,
                        x,
                        np.asarray(flat_states, dtype=np.float32),
                        np.asarray(flat_signature_indices, dtype=np.int64),
                        group_indices=np.asarray([row_index for row_index, _slot in flat_positions], dtype=np.int64),
                    )
                if self._q_backed_actor_residual_enabled():
                    scores = scores + self._q_backed_actor_residual_scores_numpy(
                        np,
                        x,
                        np.asarray(flat_states, dtype=np.float32),
                        group_indices=np.asarray([row_index for row_index, _slot in flat_positions], dtype=np.int64),
                    )
                scores = scores * np.float32(self._runtime_aux_output_scale())
                for (row_index, slot), score in zip(flat_positions, scores, strict=True):
                    row_scores_by_index[row_index][slot] = float(score)
            out.extend(self._center_legal_scores(row_scores) for row_scores in row_scores_by_index)
        return out

    def _recurrent_enabled(self) -> bool:
        mode = str(self.recurrentTrainingMode or "disabled").strip().lower()
        return bool(mode not in {"", "disabled", "none", "off", "false"} and int(self.recurrentHiddenDim) > 0)

    def _decision_residual_enabled(self) -> bool:
        return _normalize_decision_residual_policy_mode(self.decisionResidualPolicyMode) != "disabled"

    def _state_action_interaction_enabled(self) -> bool:
        if _normalize_actor_residual_contract(self.actorResidualContract) == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE:
            return False
        return (
            _normalize_state_action_interaction_mode(self.stateActionInteractionMode) != "disabled"
            and int(self.stateActionInteractionRank) > 0
        )

    def reset_recurrent_state(self) -> None:
        self._recurrentStateCache.clear()
        self._recurrentRowInitialContextCache.clear()
        self._recurrentRowContextCache.clear()

    def prune_recurrent_runtime_cache(self, *, max_state_sequences: int = 64, clear_row_context: bool = True) -> None:
        if bool(clear_row_context):
            self._recurrentRowInitialContextCache.clear()
            self._recurrentRowContextCache.clear()
            self._runtimeStateValueCache.clear()
        limit = max(1, int(max_state_sequences))
        while len(self._recurrentStateCache) > limit:
            oldest_key = next(iter(self._recurrentStateCache))
            self._recurrentStateCache.pop(oldest_key, None)

    def _score_row_recurrent_python(self, row: Mapping[str, Any], *, mask: list[bool]) -> list[float | None]:
        context = self._runtime_recurrent_context(row)
        domain = self._recurrent_domain_vector(row)
        recurrent_context = context + domain
        parts = _ygo_row_feature_parts(row, scorer=self)
        state_vector = _ygo_state_vector_from_parts(parts)
        condition_vector = self._state_action_condition_vector(
            row,
            state_vector,
            recurrent_context=recurrent_context,
        )
        legal_mean_action_vector = None
        if _state_action_mode_uses_legal_set_context(self.stateActionInteractionMode):
            legal_vectors = [
                self._state_action_base_action_vector(
                    _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
                )
                for slot, enabled in enumerate(mask)
                if enabled
            ]
            if legal_vectors:
                legal_mean_action_vector = [
                    sum(float(values[index]) for values in legal_vectors) / float(len(legal_vectors))
                    for index in range(len(legal_vectors[0]))
                ]
        scores: list[float | None] = []
        for slot, enabled in enumerate(mask):
            if not enabled:
                scores.append(None)
                continue
            vector = _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
            hidden = [
                max(0.0, float(bias) + sum(float(weight) * value for weight, value in zip(weights, vector, strict=True)))
                for weights, bias in zip(self.w1, self.b1, strict=True)
            ]
            base_score = float(self.b2) + sum(float(weight) * value for weight, value in zip(self.w2, hidden, strict=True))
            recurrent_input = vector + recurrent_context
            recurrent_hidden = [
                max(
                    0.0,
                    float(bias)
                    + sum(float(weight) * value for weight, value in zip(weights, recurrent_input, strict=True)),
                )
                for weights, bias in zip(self.recurrentPolicyW1, self.recurrentPolicyB1, strict=True)
            ]
            recurrent_score = float(self.recurrentPolicyB2) + sum(
                float(weight) * value
                for weight, value in zip(self.recurrentPolicyW2, recurrent_hidden, strict=True)
            )
            residual_score = self._decision_residual_score(row, vector)
            interaction_score = self._state_action_interaction_score(
                vector,
                condition_vector,
                row=row,
                slot=slot,
                legal_mean_action_vector=legal_mean_action_vector,
            )
            scores.append(
                (base_score + recurrent_score + residual_score + interaction_score)
                * self._runtime_aux_output_scale()
            )
        if self._q_backed_actor_residual_enabled():
            active_slots = [slot for slot, enabled in enumerate(mask) if enabled]
            active_vectors = [
                _ygo_slot_vector_from_parts(row, slot, scorer=self, parts=parts)
                for slot in active_slots
            ]
            q_residuals = self._q_backed_actor_residual_scores_for_row(
                active_vectors,
                condition_vector,
                legal_mean_action_vector=legal_mean_action_vector,
                broad_prior=[
                    float(scores[slot]) / max(1.0e-6, float(self._runtime_aux_output_scale()))
                    for slot in active_slots
                    if scores[slot] is not None
                ],
            )
            residual_by_slot = {slot: q_residuals[index] for index, slot in enumerate(active_slots)}
            scores = [
                None
                if score is None
                else float(score) + float(residual_by_slot.get(slot, 0.0)) * self._runtime_aux_output_scale()
                for slot, score in enumerate(scores)
            ]
        return self._center_legal_scores(scores)

    def _runtime_recurrent_context(self, row: Mapping[str, Any]) -> list[float]:
        hidden_dim = int(self.recurrentHiddenDim)
        if hidden_dim <= 0:
            return []
        row_key = self._recurrent_row_cache_key(row)
        cached = self._recurrentRowContextCache.get(row_key)
        if cached is not None:
            return list(cached)
        sequence_key = self._recurrent_sequence_key(row)
        metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
        reset = bool(row.get("resetHiddenState")) or bool(metadata.get("resetHiddenState"))
        previous = (
            [0.0 for _index in range(hidden_dim)]
            if reset or sequence_key not in self._recurrentStateCache
            else list(self._recurrentStateCache.get(sequence_key) or [])
        )
        if len(previous) != hidden_dim:
            previous = [0.0 for _index in range(hidden_dim)]
        state_vector = _ygo_state_vector(row, scorer=self)
        state_dim = len(self.globalFeatureNames) + len(self.historyFeatureNames) + len(self.cardFeatureNames)
        if len(state_vector) < state_dim:
            state_vector.extend(0.0 for _index in range(state_dim - len(state_vector)))
        gru_input = state_vector[:state_dim] + self._recurrent_domain_vector(row)
        hidden = self._recurrent_gru_cell(gru_input, previous)
        self._recurrentStateCache[sequence_key] = list(hidden)
        self._recurrentRowInitialContextCache[row_key] = list(previous)
        self._recurrentRowContextCache[row_key] = list(hidden)
        return list(hidden)

    def runtime_recurrent_hidden_snapshot(self, row: Mapping[str, Any]) -> dict[str, Any]:
        hidden_dim = int(self.recurrentHiddenDim)
        if not self._recurrent_enabled() or hidden_dim <= 0:
            return {"enabled": False}
        row_key = self._recurrent_row_cache_key(row)
        hidden = self._runtime_recurrent_context(row)
        initial = list(self._recurrentRowInitialContextCache.get(row_key) or [])
        if len(initial) != hidden_dim:
            initial = [0.0 for _index in range(hidden_dim)]
        metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
        reset = bool(row.get("resetHiddenState")) or bool(metadata.get("resetHiddenState"))
        return {
            "enabled": True,
            "sequenceKey": self._recurrent_sequence_key(row),
            "rowKey": row_key,
            "resetHiddenState": bool(reset),
            "initialHiddenState": [float(value) for value in initial],
            "hiddenState": [float(value) for value in hidden],
        }

    def _recurrent_gru_cell(self, values: list[float], previous: list[float]) -> list[float]:
        hidden_dim = int(self.recurrentHiddenDim)
        try:
            import numpy as np
        except ImportError:
            np = None
        if np is not None:
            weight_ih, weight_hh, bias_ih, bias_hh = self._numpy_recurrent_gru_weights(np)
            value_array = np.asarray(values, dtype=np.float32)
            previous_array = np.asarray(previous, dtype=np.float32)
            input_part = weight_ih @ value_array + bias_ih
            hidden_part = weight_hh @ previous_array + bias_hh
            reset_gate = 1.0 / (1.0 + np.exp(-(input_part[:hidden_dim] + hidden_part[:hidden_dim])))
            update_gate = 1.0 / (
                1.0
                + np.exp(
                    -(input_part[hidden_dim : 2 * hidden_dim] + hidden_part[hidden_dim : 2 * hidden_dim])
                )
            )
            new_gate = np.tanh(
                input_part[2 * hidden_dim : 3 * hidden_dim]
                + reset_gate * hidden_part[2 * hidden_dim : 3 * hidden_dim]
            )
            hidden = (1.0 - update_gate) * new_gate + update_gate * previous_array
            return [float(value) for value in hidden]

        def affine(rows: list[list[float]], bias: list[float], source: list[float]) -> list[float]:
            return [
                float(bias[index]) + sum(float(weight) * value for weight, value in zip(row, source, strict=True))
                for index, row in enumerate(rows)
            ]

        input_part = affine(self.recurrentGruWeightIh, self.recurrentGruBiasIh, values)
        hidden_part = affine(self.recurrentGruWeightHh, self.recurrentGruBiasHh, previous)
        reset_gate: list[float] = []
        update_gate: list[float] = []
        new_gate: list[float] = []
        for index in range(hidden_dim):
            reset_gate.append(_sigmoid(input_part[index] + hidden_part[index]))
            update_gate.append(_sigmoid(input_part[hidden_dim + index] + hidden_part[hidden_dim + index]))
            new_gate.append(
                math.tanh(
                    input_part[2 * hidden_dim + index]
                    + reset_gate[index] * hidden_part[2 * hidden_dim + index]
                )
            )
        return [
            (1.0 - update_gate[index]) * new_gate[index] + update_gate[index] * previous[index]
            for index in range(hidden_dim)
        ]

    def _recurrent_domain_vector(self, row: Mapping[str, Any]) -> list[float]:
        names = list(self.recurrentDomainNames or [])
        if not names:
            return []
        full_label = _outcome_policy_bucket_label(_outcome_policy_bucket_key(row))
        coarse_label = _outcome_policy_coarse_bucket_label(_outcome_policy_coarse_bucket_key(row))
        return [1.0 if name in {full_label, coarse_label} else 0.0 for name in names]

    def _recurrent_sequence_key(self, row: Mapping[str, Any]) -> str:
        metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
        for key in ("runtimeRecurrentKey", "runtimeSequenceId"):
            value = row.get(key)
            if value is None:
                value = metadata.get(key)
            text = str(value or "").strip()
            if text:
                return text
        for key in ("segmentId", "sequenceId", "episodeId", "taskId", "stateKey"):
            value = row.get(key)
            if value is None:
                value = metadata.get(key)
            text = str(value or "").strip()
            if text:
                return text
        return f"row:{id(row)}"

    def _recurrent_row_cache_key(self, row: Mapping[str, Any]) -> str:
        metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
        step = row.get("episodeStepIndex")
        if step is None:
            step = metadata.get("episodeStepIndex")
        if step is None:
            step = row.get("actionSetDecisionIndex")
        return f"{self._recurrent_sequence_key(row)}:{step}:{id(row)}"

    def _runtime_aux_output_scale(self) -> float:
        return _normalize_runtime_aux_output_scale(self.runtimeAuxOutputScale)

    def _center_legal_scores(self, scores: list[float | None]) -> list[float | None]:
        if not bool(self.centerLegalSidecarScores):
            return scores
        legal_scores = [float(score) for score in scores if score is not None]
        if not legal_scores:
            return scores
        mean_score = sum(legal_scores) / float(len(legal_scores))
        return [None if score is None else float(score) - mean_score for score in scores]

    def route_key_for_row(self, row: Mapping[str, Any]) -> str | None:
        decision = _row_route_part(row, "decisionKind")
        if decision in {"", "unknown"}:
            return None
        source = _row_route_part(row, "sourceSuiteKind", "suiteKind") or "unknown"
        turn = _row_route_part(row, "trueTurnOrder") or "unknown"
        return f"{source}|{turn}|{decision}"

    def state_value(self, row: Mapping[str, Any]) -> float:
        cached = self._runtimeStateValueCache.get(id(row))
        if cached is not None:
            return float(cached)
        state_vector = _ygo_state_vector(row, scorer=self)
        value = self._state_value_from_state_vector(row, state_vector)
        self._runtimeStateValueCache[id(row)] = float(value)
        return float(value)

    def state_values_batched(self, rows: list[Mapping[str, Any]]) -> list[float]:
        return [self.state_value(row) for row in rows]

    def _state_value_from_state_vector(
        self,
        row: Mapping[str, Any],
        state_vector: list[float],
        *,
        recurrent_context: list[float] | None = None,
    ) -> float:
        state_vector = state_vector[: len(self.valueW)]
        base_value = float(self.valueB) + sum(
            float(weight) * value for weight, value in zip(self.valueW, state_vector, strict=False)
        )
        if str(self.valueDomainBiasMode or "disabled").strip().lower() not in {"disabled", "none", "off", ""}:
            label = _outcome_policy_bucket_label(_outcome_policy_bucket_key(row))
            base_value += float((self.valueDomainBiases or {}).get(label, 0.0))
        if self._recurrent_enabled() and self.recurrentValueW:
            recurrent_value_input = (
                list(recurrent_context)
                if recurrent_context is not None
                else self._runtime_recurrent_context(row) + self._recurrent_domain_vector(row)
            )
            base_value += float(self.recurrentValueB) + sum(
                float(weight) * value
                for weight, value in zip(self.recurrentValueW, recurrent_value_input, strict=False)
            )
        return float(base_value)

    def to_dict(self) -> dict[str, Any]:
        q_backed_actor_residual_mode = _normalize_q_backed_actor_residual_mode(
            self.qBackedActorResidualMode
        )
        actor_residual_contract = _normalize_actor_residual_contract(self.actorResidualContract)
        if (
            actor_residual_contract == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE
            and q_backed_actor_residual_mode == Q_BACKED_ACTOR_RESIDUAL_DISABLED
        ):
            raise ValueError(
                "q_backed_single_residual_v1 requires qBackedActorResidualMode to be enabled"
            )
        uses_state_action_interaction = bool(self._state_action_interaction_enabled())
        return {
            "modelVersion": self.modelVersion,
            "featureFamily": YGO_STYLE_FEATURE_FAMILY,
            "globalFeatureNames": list(self.globalFeatureNames),
            "historyFeatureNames": list(self.historyFeatureNames),
            "actionFeatureNames": list(self.actionFeatureNames),
            "cardFeatureNames": list(self.cardFeatureNames),
            "inputDim": int(self.inputDim),
            "hiddenDim": int(self.hiddenDim),
            "w1": [[float(value) for value in row] for row in self.w1],
            "b1": [float(value) for value in self.b1],
            "w2": [float(value) for value in self.w2],
            "b2": float(self.b2),
            "valueW": [float(value) for value in self.valueW],
            "valueB": float(self.valueB),
            "valueDomainBiasMode": str(self.valueDomainBiasMode or "disabled"),
            "valueDomainBiases": {
                str(key): float(value)
                for key, value in sorted((self.valueDomainBiases or {}).items())
            },
            "recurrentTrainingMode": str(self.recurrentTrainingMode or "disabled"),
            "recurrentHiddenDim": int(self.recurrentHiddenDim),
            "recurrentDomainNames": [str(value) for value in self.recurrentDomainNames],
            "recurrentGruWeightIh": [[float(value) for value in row] for row in self.recurrentGruWeightIh],
            "recurrentGruWeightHh": [[float(value) for value in row] for row in self.recurrentGruWeightHh],
            "recurrentGruBiasIh": [float(value) for value in self.recurrentGruBiasIh],
            "recurrentGruBiasHh": [float(value) for value in self.recurrentGruBiasHh],
            "recurrentPolicyW1": [[float(value) for value in row] for row in self.recurrentPolicyW1],
            "recurrentPolicyB1": [float(value) for value in self.recurrentPolicyB1],
            "recurrentPolicyW2": [float(value) for value in self.recurrentPolicyW2],
            "recurrentPolicyB2": float(self.recurrentPolicyB2),
            "recurrentValueW": [float(value) for value in self.recurrentValueW],
            "recurrentValueB": float(self.recurrentValueB),
            "stateActionInteractionMode": _normalize_state_action_interaction_mode(self.stateActionInteractionMode),
            "stateActionInteractionRank": int(self.stateActionInteractionRank),
            "stateActionConditionDomainNames": [str(value) for value in self.stateActionConditionDomainNames],
            "stateActionStateW": [[float(value) for value in row] for row in self.stateActionStateW],
            "stateActionStateB": [float(value) for value in self.stateActionStateB],
            "stateActionStateCenter": [float(value) for value in self.stateActionStateCenter],
            "stateActionActionW": [[float(value) for value in row] for row in self.stateActionActionW],
            "stateActionActionB": [float(value) for value in self.stateActionActionB],
            "stateActionOutputW": [float(value) for value in self.stateActionOutputW],
            "stateActionReferenceStateW": [[float(value) for value in row] for row in self.stateActionReferenceStateW],
            "stateActionReferenceStateB": [float(value) for value in self.stateActionReferenceStateB],
            "stateActionReferenceActionW": [[float(value) for value in row] for row in self.stateActionReferenceActionW],
            "stateActionReferenceActionB": [float(value) for value in self.stateActionReferenceActionB],
            "stateActionReferenceOutputW": [float(value) for value in self.stateActionReferenceOutputW],
            "stateActionReferenceSignatureW": [[float(value) for value in row] for row in self.stateActionReferenceSignatureW],
            "stateActionCrossW": [[float(value) for value in row] for row in self.stateActionCrossW],
            "stateActionSignatureCrossW": [
                [[float(value) for value in row] for row in matrix]
                for matrix in self.stateActionSignatureCrossW
            ],
            "stateActionReferenceSignatureCrossW": [
                [[float(value) for value in row] for row in matrix]
                for matrix in self.stateActionReferenceSignatureCrossW
            ],
            "stateActionSignatureNames": [str(value) for value in self.stateActionSignatureNames],
            "stateActionSignatureW": [[float(value) for value in row] for row in self.stateActionSignatureW],
            "actionQResidualMode": str(self.actionQResidualMode or "disabled"),
            "actionQResidualFeatureDim": int(self.actionQResidualFeatureDim),
            "actionQResidualW": [float(value) for value in self.actionQResidualW],
            "actionQResidualB": float(self.actionQResidualB),
            "actionQResidualArchitecture": str(self.actionQResidualArchitecture or "disabled"),
            "actionQResidualStateDim": int(self.actionQResidualStateDim),
            "actionQResidualActionDim": int(self.actionQResidualActionDim),
            "actionQResidualRank": int(self.actionQResidualRank),
            "actionQResidualStateW": [[float(value) for value in row] for row in self.actionQResidualStateW],
            "actionQResidualStateB": [float(value) for value in self.actionQResidualStateB],
            "actionQResidualActionW": [[float(value) for value in row] for row in self.actionQResidualActionW],
            "actionQResidualOutputW": [float(value) for value in self.actionQResidualOutputW],
            "qBackedActorResidualMode": q_backed_actor_residual_mode,
            "actorResidualContract": actor_residual_contract,
            "foldedStateActionCorrection": bool(
                actor_residual_contract == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE
            ),
            "singleActorResidualCarrier": (
                "q_backed_actor_residual"
                if actor_residual_contract == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE
                else "legacy_independent_residuals"
            ),
            "independentStateActionCorrectionActive": bool(uses_state_action_interaction),
            "runtimeExportCarrier": (
                "q_backed_actor_residual"
                if q_backed_actor_residual_mode != Q_BACKED_ACTOR_RESIDUAL_DISABLED
                else "state_action_interaction_delta"
                if bool(uses_state_action_interaction)
                else "broad_prior_only"
            ),
            "baselineIncludesOldQ": bool(
                actor_residual_contract == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE
            ),
            "usesCardTokens": True,
            "usesActionMask": True,
            "usesSourceTargetCardRefs": True,
            "usesHistoryFeatures": bool(self.historyFeatureNames),
            "usesRecurrentState": bool(self._recurrent_enabled()),
            "usesStateActionInteraction": bool(uses_state_action_interaction),
            "usesDomainConditioning": bool(self.recurrentDomainNames)
            or str(self.valueDomainBiasMode or "disabled").strip().lower() not in {"disabled", "none", "off", ""},
            "policyAnchorKlTraining": bool(self.policyAnchorKlTraining),
            "anchorKlWeight": float(self.anchorKlWeight),
            "anchorKlTemperature": float(self.anchorKlTemperature),
            "anchorKlDecisionWeights": {
                str(key): float(value)
                for key, value in sorted((self.anchorKlDecisionWeights or {}).items())
            },
            "retentionKlMode": str(self.retentionKlMode or "disabled"),
            "retentionKlReport": dict(self.retentionKlReport or {}),
            "decisionTrainingWeights": {
                str(key): float(value)
                for key, value in sorted((self.decisionTrainingWeights or {}).items())
            },
            "decisionResidualPolicyMode": _normalize_decision_residual_policy_mode(self.decisionResidualPolicyMode),
            "decisionResidualWeights": {
                _decision_residual_key_from_text(key): [float(item) for item in values]
                for key, values in sorted((self.decisionResidualWeights or {}).items())
            },
            "usesDecisionResidualPolicy": bool(self._decision_residual_enabled()),
            "allowSelectedActionFallback": bool(self.allowSelectedActionFallback),
            "directPolicyTargetMode": str(self.directPolicyTargetMode),
            "runtimeAuxTrainingObjective": str(self.runtimeAuxTrainingObjective),
            "runtimeAuxTrainingDiagnostics": dict(self.runtimeAuxTrainingDiagnostics or {}),
            "runtimeAuxOutputScale": float(self._runtime_aux_output_scale()),
            "centerLegalSidecarScores": bool(self.centerLegalSidecarScores),
            "runtimeCalibratedSidecarTraining": bool(self.runtimeCalibratedSidecarTraining),
            "outcomePolicyGradientTraining": bool(self.outcomePolicyGradientTraining),
            "trainingResolvedDevice": str(self.trainingResolvedDevice),
            "scratchTraining": False,
            "defaultRuntimeChanged": False,
            "selectedActionImitation": False,
            "teacherScoreImitation": False,
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "YgoStyleActionSetPolicyScorer":
        q_backed_mode = _normalize_q_backed_actor_residual_mode(data.get("qBackedActorResidualMode"))
        actor_contract = _normalize_actor_residual_contract(data.get("actorResidualContract"))
        if actor_contract == ACTOR_RESIDUAL_CONTRACT_Q_BACKED_SINGLE:
            if q_backed_mode == Q_BACKED_ACTOR_RESIDUAL_DISABLED:
                raise ValueError(
                    "q_backed_single_residual_v1 requires qBackedActorResidualMode to be enabled"
                )
            if bool(data.get("usesStateActionInteraction", False)):
                raise ValueError(
                    "q_backed_single_residual_v1 cannot reload with independent state-action interaction enabled"
                )
            if data.get("foldedStateActionCorrection") is False:
                raise ValueError("q_backed_single_residual_v1 requires foldedStateActionCorrection=true")
            if bool(data.get("independentStateActionCorrectionActive", False)):
                raise ValueError("q_backed_single_residual_v1 forbids independent state-action correction")
            if data.get("singleActorResidualCarrier") not in {None, "", "q_backed_actor_residual"}:
                raise ValueError("q_backed_single_residual_v1 requires q_backed_actor_residual carrier")
            if data.get("runtimeExportCarrier") not in {None, "", "q_backed_actor_residual"}:
                raise ValueError("q_backed_single_residual_v1 requires q_backed_actor_residual runtime export")
            if data.get("baselineIncludesOldQ") is False:
                raise ValueError("q_backed_single_residual_v1 requires baselineIncludesOldQ=true")
        return cls(
            globalFeatureNames=[str(value) for value in list(data.get("globalFeatureNames") or [])],
            historyFeatureNames=[str(value) for value in list(data.get("historyFeatureNames") or [])],
            actionFeatureNames=[str(value) for value in list(data.get("actionFeatureNames") or [])],
            cardFeatureNames=[str(value) for value in list(data.get("cardFeatureNames") or [])],
            inputDim=int(data.get("inputDim", 0) or 0),
            hiddenDim=int(data.get("hiddenDim", 0) or 0),
            w1=[[float(value) for value in row] for row in list(data.get("w1") or [])],
            b1=[float(value) for value in list(data.get("b1") or [])],
            w2=[float(value) for value in list(data.get("w2") or [])],
            b2=float(data.get("b2", 0.0) or 0.0),
            valueW=[float(value) for value in list(data.get("valueW") or [])],
            valueB=float(data.get("valueB", 0.0) or 0.0),
            valueDomainBiasMode=str(data.get("valueDomainBiasMode") or "disabled"),
            valueDomainBiases={
                str(key): float(value)
                for key, value in dict(data.get("valueDomainBiases") or {}).items()
            },
            modelVersion=str(data.get("modelVersion") or YGO_STYLE_ACTION_SET_POLICY_VERSION),
            policyAnchorKlTraining=bool(data.get("policyAnchorKlTraining", False)),
            anchorKlWeight=float(data.get("anchorKlWeight", 0.0) or 0.0),
            anchorKlTemperature=float(data.get("anchorKlTemperature", 1.0) or 1.0),
            anchorKlDecisionWeights={
                str(key): max(0.0, float(value))
                for key, value in dict(data.get("anchorKlDecisionWeights") or {}).items()
            },
            retentionKlMode=str(data.get("retentionKlMode") or "disabled"),
            retentionKlReport=dict(data.get("retentionKlReport") or {}),
            decisionTrainingWeights={
                str(key): max(0.0, float(value))
                for key, value in dict(data.get("decisionTrainingWeights") or {}).items()
            },
            decisionResidualPolicyMode=_normalize_decision_residual_policy_mode(
                data.get("decisionResidualPolicyMode")
            ),
            decisionResidualWeights={
                _decision_residual_key_from_text(key): [float(item) for item in list(values or [])]
                for key, values in dict(data.get("decisionResidualWeights") or {}).items()
            },
            allowSelectedActionFallback=bool(data.get("allowSelectedActionFallback", False)),
            directPolicyTargetMode=str(data.get("directPolicyTargetMode") or "causal_or_explicit_only"),
            runtimeAuxTrainingObjective=_normalize_runtime_aux_training_objective(
                data.get("runtimeAuxTrainingObjective")
            ),
            runtimeAuxTrainingDiagnostics=dict(data.get("runtimeAuxTrainingDiagnostics") or {}),
            runtimeAuxOutputScale=_normalize_runtime_aux_output_scale(data.get("runtimeAuxOutputScale", 1.0)),
            centerLegalSidecarScores=bool(data.get("centerLegalSidecarScores", False)),
            runtimeCalibratedSidecarTraining=bool(data.get("runtimeCalibratedSidecarTraining", False)),
            outcomePolicyGradientTraining=bool(data.get("outcomePolicyGradientTraining", False)),
            trainingResolvedDevice=str(data.get("trainingResolvedDevice") or "unknown"),
            recurrentTrainingMode=str(data.get("recurrentTrainingMode") or "disabled"),
            recurrentHiddenDim=int(data.get("recurrentHiddenDim", 0) or 0),
            recurrentDomainNames=[str(value) for value in list(data.get("recurrentDomainNames") or [])],
            recurrentGruWeightIh=[
                [float(value) for value in row]
                for row in list(data.get("recurrentGruWeightIh") or [])
            ],
            recurrentGruWeightHh=[
                [float(value) for value in row]
                for row in list(data.get("recurrentGruWeightHh") or [])
            ],
            recurrentGruBiasIh=[float(value) for value in list(data.get("recurrentGruBiasIh") or [])],
            recurrentGruBiasHh=[float(value) for value in list(data.get("recurrentGruBiasHh") or [])],
            recurrentPolicyW1=[
                [float(value) for value in row]
                for row in list(data.get("recurrentPolicyW1") or [])
            ],
            recurrentPolicyB1=[float(value) for value in list(data.get("recurrentPolicyB1") or [])],
            recurrentPolicyW2=[float(value) for value in list(data.get("recurrentPolicyW2") or [])],
            recurrentPolicyB2=float(data.get("recurrentPolicyB2", 0.0) or 0.0),
            recurrentValueW=[float(value) for value in list(data.get("recurrentValueW") or [])],
            recurrentValueB=float(data.get("recurrentValueB", 0.0) or 0.0),
            stateActionInteractionMode=_normalize_state_action_interaction_mode(
                data.get("stateActionInteractionMode")
            ),
            stateActionInteractionRank=int(data.get("stateActionInteractionRank", 0) or 0),
            stateActionConditionDomainNames=[
                str(value) for value in list(data.get("stateActionConditionDomainNames") or [])
            ],
            stateActionStateW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionStateW") or [])
            ],
            stateActionStateB=[float(value) for value in list(data.get("stateActionStateB") or [])],
            stateActionStateCenter=[float(value) for value in list(data.get("stateActionStateCenter") or [])],
            stateActionActionW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionActionW") or [])
            ],
            stateActionActionB=[float(value) for value in list(data.get("stateActionActionB") or [])],
            stateActionOutputW=[float(value) for value in list(data.get("stateActionOutputW") or [])],
            stateActionReferenceStateW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionReferenceStateW") or [])
            ],
            stateActionReferenceStateB=[float(value) for value in list(data.get("stateActionReferenceStateB") or [])],
            stateActionReferenceActionW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionReferenceActionW") or [])
            ],
            stateActionReferenceActionB=[float(value) for value in list(data.get("stateActionReferenceActionB") or [])],
            stateActionReferenceOutputW=[
                float(value) for value in list(data.get("stateActionReferenceOutputW") or [])
            ],
            stateActionReferenceSignatureW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionReferenceSignatureW") or [])
            ],
            stateActionCrossW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionCrossW") or [])
            ],
            stateActionSignatureCrossW=[
                [[float(value) for value in row] for row in matrix]
                for matrix in list(data.get("stateActionSignatureCrossW") or [])
            ],
            stateActionReferenceSignatureCrossW=[
                [[float(value) for value in row] for row in matrix]
                for matrix in list(data.get("stateActionReferenceSignatureCrossW") or [])
            ],
            stateActionSignatureNames=[str(value) for value in list(data.get("stateActionSignatureNames") or [])],
            stateActionSignatureW=[
                [float(value) for value in row]
                for row in list(data.get("stateActionSignatureW") or [])
            ],
            actionQResidualMode=str(data.get("actionQResidualMode") or "disabled"),
            actionQResidualFeatureDim=int(data.get("actionQResidualFeatureDim", 0) or 0),
            actionQResidualW=[float(value) for value in list(data.get("actionQResidualW") or [])],
            actionQResidualB=float(data.get("actionQResidualB", 0.0) or 0.0),
            actionQResidualArchitecture=str(data.get("actionQResidualArchitecture") or "disabled"),
            actionQResidualStateDim=int(data.get("actionQResidualStateDim", 0) or 0),
            actionQResidualActionDim=int(data.get("actionQResidualActionDim", 0) or 0),
            actionQResidualRank=int(data.get("actionQResidualRank", 0) or 0),
            actionQResidualStateW=[
                [float(value) for value in row]
                for row in list(data.get("actionQResidualStateW") or [])
            ],
            actionQResidualStateB=[float(value) for value in list(data.get("actionQResidualStateB") or [])],
            actionQResidualActionW=[
                [float(value) for value in row]
                for row in list(data.get("actionQResidualActionW") or [])
            ],
            actionQResidualOutputW=[float(value) for value in list(data.get("actionQResidualOutputW") or [])],
            qBackedActorResidualMode=q_backed_mode,
            actorResidualContract=actor_contract,
        )

    @classmethod
    def from_feature_weights(
        cls,
        *,
        global_feature_names: list[str],
        action_feature_names: list[str],
        card_feature_names: list[str],
        history_feature_names: list[str] | None = None,
        source_card_feature_weights: Mapping[str, float] | None = None,
        target_card_feature_weights: Mapping[str, float] | None = None,
        action_feature_weights: Mapping[str, float] | None = None,
        global_feature_weights: Mapping[str, float] | None = None,
        history_feature_weights: Mapping[str, float] | None = None,
    ) -> "YgoStyleActionSetPolicyScorer":
        history_names = list(history_feature_names or [])
        input_dim = len(global_feature_names) + len(history_names) + len(action_feature_names) + 3 * len(card_feature_names)
        weights = [0.0 for _index in range(input_dim)]
        global_offset = 0
        history_offset = global_offset + len(global_feature_names)
        action_offset = history_offset + len(history_names)
        pooled_offset = action_offset + len(action_feature_names)
        source_offset = pooled_offset + len(card_feature_names)
        target_offset = source_offset + len(card_feature_names)
        for names, offset, feature_weights in (
            (global_feature_names, global_offset, global_feature_weights or {}),
            (history_names, history_offset, history_feature_weights or {}),
            (action_feature_names, action_offset, action_feature_weights or {}),
            (card_feature_names, source_offset, source_card_feature_weights or {}),
            (card_feature_names, target_offset, target_card_feature_weights or {}),
        ):
            for name, value in feature_weights.items():
                if name in names:
                    weights[offset + names.index(name)] = float(value)
        return cls(
            globalFeatureNames=list(global_feature_names),
            historyFeatureNames=history_names,
            actionFeatureNames=list(action_feature_names),
            cardFeatureNames=list(card_feature_names),
            inputDim=input_dim,
            hiddenDim=1,
            w1=[weights],
            b1=[0.0],
            w2=[1.0],
            b2=0.0,
            valueW=[0.0 for _index in range(len(global_feature_names) + len(history_names) + len(card_feature_names))],
        )


