def _outcome_policy_domain_opponent_id(
    row: Mapping[str, Any],
    metadata: Mapping[str, Any],
    *,
    rollout_pool_kind: str,
) -> str:
    raw = (
        metadata.get("runtimeOpponentPolicyId")
        or metadata.get("subjectOpponentPolicyId")
        or row.get("runtimeOpponentPolicyId")
        or "unknown"
    )
    if str(rollout_pool_kind) == "current_selfplay":
        return "selfplay_current_actor"
    return str(raw)


def _outcome_policy_bucket_key(row: Mapping[str, Any]) -> tuple[str, str, str, str, str, str]:
    metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
    pool = str(metadata.get("rolloutPoolKind") or row.get("rolloutPoolKind") or "unknown")
    suite = str(metadata.get("suiteKind") or row.get("suiteKind") or metadata.get("sourceSuiteKind") or "unknown")
    opponent = _outcome_policy_domain_opponent_id(
        row,
        metadata,
        rollout_pool_kind=pool,
    )
    side = str(metadata.get("runtimeActorSide") or metadata.get("modelSide") or row.get("modelSide") or "unknown")
    player_deck = str(metadata.get("playerDeckId") or metadata.get("modelDeckId") or row.get("playerDeckId") or row.get("modelDeckId") or "unknown")
    opponent_deck = str(
        metadata.get("opponentDeckId")
        or metadata.get("oldTop10DeckId")
        or row.get("opponentDeckId")
        or row.get("oldTop10DeckId")
        or "unknown"
    )
    return pool, suite, opponent, side, player_deck, opponent_deck


def _outcome_policy_coarse_bucket_key(row: Mapping[str, Any]) -> tuple[str, str, str, str]:
    return _outcome_policy_bucket_key(row)[:4]


def _normalize_value_domain_bias_mode(mode: str | None) -> str:
    text = str(mode or "disabled").strip().lower()
    if text in {"", "disabled", "none", "off", "false"}:
        return "disabled"
    if text in {"matchup_bucket", "bucket", "per_matchup", "domain_bucket"}:
        return "matchup_bucket"
    raise ValueError(f"unknown value_domain_bias_mode: {mode!r}")


def _normalize_recurrent_training_mode(mode: str | None) -> str:
    text = str(mode or "disabled").strip().lower()
    if text in {"", "disabled", "none", "off", "false"}:
        return "disabled"
    if text in {"gru_domain_v1", "domain_gru_v1", "recurrent_domain_v1"}:
        return "gru_domain_v1"
    raise ValueError(f"unknown recurrent_training_mode: {mode!r}")


def _normalize_decision_residual_policy_mode(mode: str | None) -> str:
    text = str(mode or "disabled").strip().lower()
    if text in {"", "disabled", "none", "off", "false"}:
        return "disabled"
    if text in {"linear", "linear_v1", "per_decision_linear_v1", "decision_linear_v1"}:
        return "linear_v1"
    raise ValueError(f"unknown decision_residual_policy_mode: {mode!r}")


def _normalize_state_action_interaction_mode(mode: str | None) -> str:
    text = str(mode or "disabled").strip().lower()
    if text in {"", "disabled", "none", "off", "false"}:
        return "disabled"
    if text in {"low_rank", "low_rank_v1", "state_action_low_rank_v1"}:
        return "low_rank_v1"
    if text in {"low_rank_v2", "state_action_low_rank_v2", "low_rank_output_v2"}:
        return "low_rank_v2"
